\label{defJfunctionalrelation}
	In a presheaf topos $[{\cal C}^{\textup{op}}, \Set]$, a relation $R\mono P\times Q$ (that is, an assignment $c\to R(c)$ to each object $c$ of $\cal C$ of a subset $R(c)$ of $P(c)\times Q(c)$ which is \emph{functorial} in the sense that for any arrow $f:c\to c'$ in $\cal C$, $P(f)\times Q(f)$ sends $R(c')$ to $R(c)$), is said to be \emph{$J$-functional from $P$ to $Q$} if it satisfies the following properties:
	\begin{enumerate}[(i)]
		\item for any $c\in {\cal C}$ and any $(x, y)\in P(c)\times Q(c)$,\\ if $\{f:d\to c \mid\ (P(f)(x), Q(f)(y))\in R(d)\}\in J(c)$ then $(x,y)\in R(c)$;

		\item for any $c\in {\cal C}$ and any $(x, y), (x', y')\in R(c)$, if $x=x'$ then $\{f:d\to c \mid Q(f)(y)=Q(f)(y')\}\in J(c)$;

		\item for any $c\in {\cal C}$ and any $x\in P(c)$, $\{f:d\to c \mid \exists y\in Q(d) \,(P(f)(x), y)\in R(d) \}\in J(c)$.
	\end{enumerate}

\label{propfuncionalassignment}
	We have a natural bijection between the $J$-functional relations $R$ from $P$ to $Q$ and the functions $f$ assigning to each element $x\in P(c)$ a $\equiv_{J}$-equivalence class of elements of $Q(c)$ (that is, a subset $A$ of $Q(c)$ such that for any $y\in A$ and $y'\in Q(c)$, $y\equiv_{J} y'$ if and only if $y'\in A$) which is \emph{functorial} in the sense that for any arrow $g:d\to c$ in $\cal C$, if $y\in f(x)$ then $Q(g)(y)\in f(P(g)(x))$, \emph{$J$-closed} in the sense that if $Q(g)(y)\in f(P(g)(x))$ for all the arrows $g$ of a $J$-covering sieve then $y\in f(x)$ and \emph{$J$-locally pointed} in the sense that for any $x\in P(c)$, $\{g:d\to c \mid f(P(g)(x))\neq \emptyset \}\in J(c)$. This correspondence sends 
	\begin{itemize}
		\item a function $f$ satisfying the above properties to the relation $R_{f}\mono P\times Q$ consisting of the pairs $(x, y)$ such that $y\in f(x)$;

		\item a $J$-functional relation $R$ from $P$ to $Q$ to the function $f_{R}$ given by:
		\[
		f_{R}(x)=\{y\in Q(c) \mid (x, y)\in R(c)\}
		\]
		for any $x\in P(c)$.
	\end{itemize}

\label{thmfunctionalrelations}
	Let $({\cal C}, J)$ be a small-generated site. Then, for any presheaves $P,Q\in [{\cal C}^{\textup{op}},\Set]$, the arrows $a_{J}(P)\to a_{J}(Q)$ in $\Sh({\cal C}, J)$ are in natural bijection with the $J$-functional relations from $P$ to $Q$ in $[{\cal C}^{\textup{op}},\Set]$.

	Moreover, under this bijection, the composition of arrows in $\Sh({\cal C}, J)$ corresponds to the $c_{J}$-closure of the composition in $[{\cal C}^{\textup{op}},\Set]$ of the associated $J$-functional relations. This operation, which we shall denote by the symbol $\ast$, admits the following explicit description: given a $J$-functional relation $R$ from $P$ to $Q$ and a $J$-functional relation $S$ from $Q$ to $Z$, $S\ast R$ is given by the formula
	\begin{equation*}\begin{split}
	(S\ast R)(c)&=\{(x, z)\in P(c)\times Z(c) \mid \{f:d\to c \mid \exists y\in Q(d)\, \\
	& \quad\quad(P(f)(x), y)\in R(d)\textup{ and } (y, Z(f)(z))\in S(d)\}\in J(c) \}
	\end{split}\end{equation*}
	for any $c\in {\cal C}$.

\label{corfullsubcategorytopos}
	Let $({\cal C}, J)$ be a small-generated site. Then the full subcategory $a_{J}({\cal C})$ of $\Sh({\cal C}, J)$ on the objects of the form $l(c)$ for $c\in {\cal C}$ is equivalent to the category ${\cal C}_{J}$ defined as follows: 
	\begin{itemize}
		\item the objects of ${\cal C}_{J}$ are the objects of $\cal C$; 

		\item the arrows $c\to d$ are the collections $R$ of pairs of arrows $(f:e\to c,g:e\to d)$ where $e$ varies among the objects of $\cal C$ (we write $(f, g)\in R(e)$ to mean that $(f, g)\in R$ and $\textup{dom}(f)=\textup{dom}(g)=e$) satisfying the following properties:

		\begin{enumerate}[(i)]
			\item for any arrow $k:e'\to e$, if $(f,g)\in R$ then $(f\circ k, g\circ k)\in R$; 

			\item for any $e\in {\cal C}$ and any arrows $x:e\to c, y:e\to d$, if $\{f:e'\to e \mid\ (x\circ f, y\circ f)\in R\}\in J(e)$ then $(x, y)\in R$; 

			\item for any $e\in {\cal C}$ and any $(x, y), (x', y')\in R(e)$, if $x=x'$ then $\{f:e'\to e \mid y\circ f=y'\circ f\}\in J(e)$;

			\item for any $e\in {\cal C}$ and any $x:e\to c$, $\{f:e'\to e \mid \exists y:e'\to d \text{ such that } (x\circ f, y)\in R(e') \}\in J(e)$;
		\end{enumerate}

		\item the composite $S\ast R$ of two arrows $R:c\to d$ and $S:d\to a$ is given by the following formula: 
		\begin{equation*}\begin{split}
		(S\ast R)(e)&=\{(x:e\to c, z:e\to a) \mid \{f:e'\to e \mid \exists y:e'\to d\, \\
		& \quad\quad(x\circ f, y)\in R(e')\textup{ and } (y, z\circ f)\in S(e')\}\in J(e) \}
		\end{split}\end{equation*}
		for any $e\in {\cal C}$. 
	\end{itemize}

	One half of the equivalence ${\cal C}_{J}\simeq a_{J}({\cal C})$ is given by the functor ${\cal C}_{J}\to a_{J}({\cal C})$ acting on objects by sending any $c\in {\cal C}_{J}$ to $l(c)$ and any arrow $R:c\to c'$ in ${\cal C}_{J}$ to the arrow $l(c)\to l(c')$ in $a_{J}({\cal C})$ whose graph is $a_{J}(R)$.

\label{corhyperconnectedsieves}
	Let $({\cal C}, J)$ be a small-generated site. Then the full subcategory of $\Sh({\cal C}, J)$ on the objects of the form $a_{J}(S)$ for $c\in {\cal C}$ and $S$ a ($J$-closed) sieve on $c$ is equivalent to the category ${\cal C}_{J}^{s}$ defined as follows: 
	\begin{itemize}
		\item the objects of ${\cal C}_{J}^{s}$ are the pairs $(c, S)$ consisting of an object $c$ of $\cal C$ and a ($J$-closed) sieve $S$ on $c$; 

		\item the arrows $(c, S)\to (d, T)$ are the collections $R$ of pairs of arrows $(x:e\to c,y:e\to d)$ where $e$ varies among the objects of $\cal C$ (we write $(x, y)\in R(e)$ to mean that $(x, y)\in R$ and $\textup{dom}(x)=\textup{dom}(y)=e$) satisfying the following properties:

		\begin{enumerate}[(i)]
			\item for any $(x,y)\in R$, $x\in S$ and $y\in T$;

			\item for any arrow $f:e'\to e$, if $(x,y)\in R$ then $(x\circ f, y\circ f)\in R$; 

			\item for any $e\in {\cal C}$ and any $(x:e\to c, y:e\to d)\in S\times T$,  if $\{f:e'\to e \mid\ (x\circ f, y\circ f)\in R\}\in J(e)$ then $(x,y)\in R$; 

			\item for any $e\in {\cal C}$ and any $(x, y), (x', y')\in R(e)$, if $x=x'$ then $\{f:e'\to e \mid y\circ f=y'\circ f\}\in J(e)$;

			\item for any $e\in {\cal C}$ and any $x:e\to c$ in $S$, $\{f:e'\to e \mid \exists y:e'\to d \text{ such that } (x\circ f, y)\in R(e') \}\in J(e)$;
		\end{enumerate}

		\item the composite $R'\ast R:(c, S)\to (a, Z)$ of two arrows $R:(c, S)\to (d, T)$ and $R':(d, T)\to (a, Z)$ is given by the following formula: 
		\begin{equation*}\begin{split}
		(R'\ast R)(e)&=\{(x:e\to c, z:e\to a)\in S\times Z \mid \{f:e'\to e \mid \exists y:e'\to d\, \\
		& \quad\quad(x\circ f, y)\in R(e')\textup{ and } (y, z\circ f)\in R'(e')\}\in J(e) \}
		\end{split}\end{equation*}
		for any $e\in {\cal C}$. 
	\end{itemize}

\label{propfunctionalrelationmonoepi}
	Let $R$ be a $J$-functional relation from $P$ to $Q$ in $[{\cal C}^{\textup{op}}, \Set]$ and $\alpha_{R}:a_{J}(P)\to a_{J}(Q)$ the arrow in $\Sh({\cal C}, J)$ induced by $R$. Then 
	\begin{enumerate}[(i)]
		\item  $\alpha_{R}$ is a monomorphism if and only if for any $c\in {\cal C}$ and any elements $(x,y), (x',y')\in R(c)$ such that $y=y'$, the sieve $\{f:d\to c \mid P(f)(x)=P(f)(x')\}$ is $J$-covering.

		\item  $\alpha_{R}$ is an epimorphism if and only if for any $c\in {\cal C}$ and $y\in Q(c)$, the sieve $\{f:d\to c \mid (\exists x\in P(d))((x, Q(f)(y))\in R(d))\}$ is $J$-covering.
	\end{enumerate}

\label{propsheafification}
	Let $({\cal C}, J)$ be a small-generated site. Then 
	\begin{enumerate}[(i)]
		\item An arrow $\xi:l(c)\to a_{J}(P)$ in $\Sh({\cal C}, J)$ (equivalently, an element of $a_{J}(P)(c)$) can be identified with an equivalence class of families $\{x_{f}\in P(\textup{dom}(f)) \mid f\in S\}$ of elements of $P$ indexed by the arrows $f$ of a $J$-covering sieve $S$ on $c$ which are \emph{locally matching} in the sense that for any arrow $g$ composable with an arrow $f\in S$, $x_{f\circ g}\equiv_{J} P(g)(x_{f})$, modulo the equivalence which identifies two such families when they are locally equal on a common refinement. 

		\item Any such family yields a local representation of $\xi$ in the sense that $\xi\circ l(f)=r_{x_{f}}$ for each $f\in S$, where $r_{x_{f}}$ is the image under $a_{J}$ of the arrow $y_{\cal C}(\textup{dom}(f))\to P$ corresponding to the element $x_{f}\in P(\textup{dom}(f))$ via the Yoneda lemma. 

		\item Alternatively, the elements of $a_{J}(P)(c)$ can be identified with functions sending to each arrow $f:d\to c$ in $\cal C$ a (possibly empty) $\equiv_{J}$-equivalence class $C_{f}\subseteq P(\textup{dom}(f))$ of elements of $P(\textup{dom}(f))$ in such a way that 
		\begin{itemize}
			\item for any $g$ composable with $f$, $P(g)(C_{f})\subseteq C_{f\circ g}$;

			\item for any $y\in P(\textup{dom}(f))$, if $\{g:\textup{dom}(g)\to \textup{dom}(f) \mid P(g)(y)\in C_{f\circ g}\}\in J(\textup{dom}(f))$ then $y\in C_{f}$;

			\item $\{g:\textup{dom}(g)\to \textup{dom}(f) \mid C_{f\circ g}\neq \emptyset \}\in J(\textup{dom}(f))$.
		\end{itemize}    
	\end{enumerate}

\label{defrelcofinality}
	Given a small site $({\cal C}, J)$, a functor $F:{\cal A}\to {\cal C}$ is said to be \emph{$J$-cofinal} if the following conditions are satisfied:
	\begin{enumerate}[(i)]
		\item For any object $c$ of $\cal C$ there are a $J$-covering family $\{f_i: c_i \to c \mid i\in I\}$ and for each $i\in I$ an object $a_{i}$ of $\cal A$ and an arrow $y_i:c_{i}\to F(a_{i})$.

		\item For any object $c$ of $\cal C$ and any arrows $x:c\to F(a)$ and $x':c\to F(b)$ in $\cal C$ there is a $J$-covering family $\{f_i: c_i \to c \mid i\in I\}$ such that $x\circ f_i$ and $x'\circ f_i$ belong to the same connected component of the category $(c_i \downarrow F)$ for each $i\in I$. 
	\end{enumerate}

\label{corcofinalcharacterization}
	Let $({\cal C}, J)$ be a small-generated site and $F:{\cal A}\to {\cal C}$	a functor. Then $F$ is $J$-cofinal if and only if the canonical arrow
	\[
	\textup{colim}_{\Sh({\cal C}, J)}(l\circ F) \to 1_{\Sh({\cal C}, J)}
	\] 
	is an isomorphism.

\label{corcolimitintopos}
	Let $D:{\cal A}\to {\cal C}$ be a functor and $\xi$ a cocone $\{\xi_{a}: D(a)\to c_{0} \mid a\in {\cal A}\}$ under $D$ with vertex $c_{0}$. Then $\xi$ is sent by the canonical functor $l:{\cal C}\to \Sh({\cal C}, J)$ to a colimit cocone if and only if the functor $D_{\xi}$ is $J_{c_{0}}$-cofinal, equivalently if and only if the following conditions are satisfied:
	\begin{enumerate}[(i)]
		\item For any object $c$ of $\cal C$ and any arrow $y:c\to c_{0}$ in $\cal C$ there are a $J$-covering family $\{f_i: c_i \to c \mid i\in I\}$ and for each $i\in I$ an object $a_{i}$ of $\cal A$ and an arrow $y_i:c_{i}\to D(a_{i})$ such that $y\circ f_{i}=\xi_{a_{i}}\circ y_{i}$.

		\item For any object $c$ of $\cal C$ and any arrows $x:c\to D(a)$ and $x':c\to D(b)$ in $\cal C$ such that $\xi_{a}\circ x= \xi_{b}\circ x'$ there is a $J$-covering family $\{f_i: c_i \to c \mid i\in I\}$ such that $x\circ f_i$ and $x'\circ f_i$ belong to the same connected component of the category $(c_{i} \downarrow D)$ for each $i\in I$. 
	\end{enumerate}

\label{filteringfunctor}
	A functor $A:{\cal C}\to {\cal E}$ is flat if and only if it is filtering in the sense that it satisfies the following conditions:	
	\begin{enumerate}[(i)]
		\item The family of arrrows $A(c)\to 1_{\cal E}$ (for $c\in {\cal C}$) is epimorphic in $\cal E$;

		\item For any objects $c$ and $d$ of $\cal C$, the family of arrows of the form $\langle A(u), A(v)\rangle :A(b)\to A(c)\times A(d)$, where $b$ is an object of $\cal C$ $u$ and $v$ are arrows respectively $b\to c$ and $b\to d$ in $\cal C$, is epimorphic in $\cal E$;

		\item For any two arrows $u, v:c\to d$ in $\cal C$, let $i:\textup{Eq}(A(u), A(v))\mono A(c)$ be the equalizer of $A(u)$ and $A(v)$ in $\cal E$. Then the family of factorizations $A(b)\to \textup{Eq}(A(u), A(v))$ through $i$ of arrows of the form $A(w):A(b)\to A(c)$, where $w:b\to c$ is an arrow in $\cal C$ such that $u\circ w=v\circ w$, is epimorphic. 		
	\end{enumerate}

\label{corliftcomorphismsofsites}
	Let $G:{\cal A}\to {\cal C}$ and $F:{\cal C}\to {\cal D}$ be functors such that $F\circ G$ is a comorphism of sites $({\cal A}, A)\to ({\cal D}, L)$. Then $G$ is a comorphism of sites $({\cal A}, A)\to ({\cal C}, M^{F}_{L})$.

	If $F$ is full and faithful, then $F:({\cal C}, M^{F}_{L})\to ({\cal D}, L)$ is cover-reflecting.

\label{propadjointinduction}
	Let $({\cal C}, J)$ and $({\cal D}, K)$ be small-generated sites, and $F:{\cal C}\to {\cal D}\dashv G:{\cal D}\to {\cal C}$ adjoint functors. Then
	\begin{enumerate}[(i)]
		\item $F$ has the covering-lifting property if and only if $G$ is cover-preserving.

		\item $G$ is a morphism of sites $({\cal D}, T_{\cal D})\to ({\cal C}, T_{\cal C})$, where $T_{\cal C}$ and $T_{\cal D}$ are the trivial topologies respectively on $\cal C$ and $\cal D$, and induces an essential geometric morphism $[{\cal C}^{\textup{op}}, \Set]\to [{\cal D}^{\textup{op}}, \Set]$;

		\item $G$ is a morphism of sites $({\cal D}, K) \to ({\cal C}, J)$ (equivalently, by (i), $G$ is cover-preserving) if and only if $F$ is a comorphism of sites $({\cal C}, J)\to ({\cal D}, K)$.

		\item In the situation of (iii), the geometric morphism $C_{F}$ induced by $F$ co-incides with the geometric morphism $\Sh(G)$ induced by $G$.
	\end{enumerate}

\label{thmmorphismtocomorphism}
	Let $F:({\cal C}, J)\to ({\cal D}, K)$ be a morphism of small-generated sites. Let $i_{F}$ be the functor ${\cal C}\to (1_{\cal D}\downarrow F)$ sending any object $c$ of $\cal C$ to the triplet $(F(c), c, 1_{F(c)})$ (and acting on arrows in the obvious way), and $\pi_{\cal C}: (1_{\cal D}\downarrow F) \to {\cal C}$ and $\pi_{\cal D}: (1_{\cal D}\downarrow F) \to {\cal D}$ the canonical projection functors. Let $\tilde{K}$ be the Grothendieck topology on $ (1_{\cal D}\downarrow F)$ whose covering sieves are those whose image under $\pi_{\cal D}$ is $K$-covering. Then
	\begin{enumerate}[(i)]
		\item $\pi_{\cal C} \dashv i_{F}$, $\pi_{\cal D}\circ i_{F}=F$, $i_{F}$ is a morphism of sites $({\cal C}, J)\to ((1_{\cal D}\downarrow F), \tilde{K})$ and $c_{F}:=\pi_{\cal C}$ is a comorphism of sites $((1_{\cal D}\downarrow F), \tilde{K}) \to ({\cal C}, J)$; 	

		\item $\pi_{\cal D}: ((1_{\cal D}\downarrow F), \tilde{K}) \to ({\cal D}, K)$ is both a ($\tilde{K}$-full, $K$-dense and cover-reflecting) morphism of sites and a comorphism of sites inducing equivalences
		\[
		C_{\pi_{\cal D}}:\Sh((1_{\cal D}\downarrow F), \tilde{K}) \to \Sh({\cal D}, K)
		\]
		and
		\[
		\Sh(\pi_{\cal D}):\Sh({\cal D}, K) \to \Sh((1_{\cal D}\downarrow F), \tilde{K})
		\] 
		which are quasi-inverse to each other and make the following triangle commute:
		\begin{equation*}
		\begin{tikzcd}
		\Sh((1_{\cal D}\downarrow F), \tilde{K}) \arrow[rr, "C_{\pi_{\cal D}}", yshift=1ex] \ar[rr, phantom, "\sim"{yshift=-0.25ex}]  \arrow[dr, "C_{\pi_{\cal C}}\cong \Sh(i_{F})"{below, xshift=-5ex}]   & &  \Sh({\cal D}, K) \ar[ll, "\Sh(\pi_{\cal D})", yshift=-1ex] \ar[ld, "\Sh(F)", yshift=0.5ex, xshift=-1ex]            \\
		& \Sh({\cal C}, J)  & 
		\end{tikzcd}
		\end{equation*}	
	\end{enumerate}

\label{thmcomorphismtomorphism}
	Let $F:({\cal D}, K)\to ({\cal C}, J)$ be a comorphism of small-generated sites. Let $\pi_{\cal C}':(F \downarrow 1_{\cal C})\to {\cal C}$ and  $\pi_{\cal D}':(F \downarrow 1_{\cal C})\to {\cal D}$ be the canonical projection functors and $j_{F}:{\cal D}\to (F \downarrow 1_{\cal C})$ the functor sending any object $d$ of $\cal D$ to the triplet $(d, F(d), 1_{F(d)})$. Let $\overline{K}$ be the Grothendieck topology on $(F \downarrow 1_{\cal C})$ whose covering families are those which are sent by $\pi_{\cal D}'$ to $K$-covering families. Then

	\begin{enumerate}[(i)]
		\item $j_{F}\dashv \pi_{\cal D}'$, $\pi_{\cal C}'\circ j_{F}=F$, $\pi_{\cal C}'$ is a comorphism of sites $(F \downarrow 1_{\cal C}, \overline{K})\to ({\cal C}, J)$ and $j_{F}$ is a (full and faithful) comorphism and dense morphism of sites $({\cal D}, K) \to (F \downarrow 1_{\cal C}, \overline{K})$; 

		\item $\pi_{\cal D}'$ is both a morphism and a comorphism of sites  $((F \downarrow 1_{\cal C}), \overline{K})\to ({\cal D}, K)$
		inducing equivalences
		\[
		C_{\pi_{D}'}:\Sh((F \downarrow 1_{\cal C}), \overline{K})\to \Sh({\cal D}, K)
		\]  
		and
		\[
		\Sh(\pi_{D}'):\Sh({\cal D}, K) \to \Sh((F \downarrow 1_{\cal C}), \overline{K})
		\] 
		which are quasi-inverse to each other and make the following triangle commute:
		\begin{equation*}
		\begin{tikzcd}
		\Sh((F \downarrow 1_{\cal C}), \overline{K}) \arrow[rr, "C_{\pi_{\cal D}'}\cong \Sh(j_{F})", yshift=1ex] \ar[rr, phantom, "\sim"{yshift=-0.25ex}]  \arrow[dr, "C_{\pi_{\cal C}'}"{below, xshift=-2ex}]   & &  \Sh({\cal D}, K) \ar[ll, "\Sh(\pi_{\cal D}')\cong C_{j_{F}}", yshift=-1ex] \ar[ld, "C_{F}", yshift=0.5ex, xshift=-1ex]            \\
		& \Sh({\cal C}, J)  & 
		\end{tikzcd}
		\end{equation*}	

		\item With $F$ we can associate a morphism of sites $m_{F}:({\cal C}, J)\to (\hat{\cal D}, \hat{K})$, where $m_{F}$ is the functor sending an object $c$ of $\cal C$ to the presheaf $\textup{Hom}_{\cal C}(F(-), c)$ and $\hat{K}$ is the extension of the Grothendieck topology $K$ along the Yoneda embedding ${\cal D}\rightarrow \hat{\cal D}$ (in the sense of section \ref{sec:presheaflifting}), which induces a geometric morphism $\Sh(m_{F})$ making the following triangle commute:  
		\begin{equation*}
		\begin{tikzcd}
		\Sh(\hat{D}, \hat{K}) \arrow[rr, "\Sh(y_{\cal D})", yshift=1ex] \ar[rr, phantom, "\sim"{yshift=-0.25ex}]  \arrow[dr, "\Sh(m_{F})"{below, xshift=-2ex}]   & &  \Sh({\cal D}, K) \ar[ll, "C_{y_{\cal D}}", yshift=-1ex] \ar[ld, "C_{F}", yshift=0.5ex, xshift=-1ex]            \\
		& \Sh({\cal C}, J)  & 
		\end{tikzcd}
		\end{equation*}	
	\end{enumerate}

\label{thmtoposadjunction}
	Let $({\cal C}, J)$ and $({\cal D}, K)$ be small-generated sites.

	\begin{enumerate}[(i)]
		\item Let $F:({\cal C}, J)\to ({\cal D}, K)$ be a morphism of sites, with corresponding comorphism of sites $c_{F}:((1_{\cal D}\downarrow F), \tilde{K}) \to ({\cal C}, J)$ as in Theorem \ref{thmmorphismtocomorphism}. Let $\pi_{\cal D}:((1_{\cal D} \downarrow F), \tilde{K})\to ({\cal D}, K)$ be the canonical projection functor, and let 
		\[
		w_{F}: (1_{\cal D}\downarrow F)\to (c_{F}\downarrow 1_{\cal D})
		\]
		be the functor $j_{c_{F}}$, sending an object $A$ of $(1_{\cal D}\downarrow F)$ to the object $(A, c_{F}(A), 1_{c_{F}(A)}:c_{F}(A)\to c_{F}(A))$. Then $w_{F}$ is both a (full and faithful) comorphism and a dense morphism of sites $((1_{\cal D}\downarrow F),  \tilde{K}) \to ((c_{F}\downarrow 1_{\cal D}), \overline{\tilde{K}})$ satisfying the relation $\pi_{\cal D}'''\circ w_{F}=\pi_{\cal D}$ and inducing an equivalence relating $F$ and $c_{F}$, which makes the following diagram commute (where $\pi_{\cal D}'''$ denotes the canonical projection functor $(c_{F}\downarrow 1_{\cal D}) \to {\cal D}$):
		\begin{equation*}
		\begin{tikzcd} 
		\Sh({\cal D}, K) \ar[d, "\Sh(\pi_{{\cal D}'''})", xshift=1ex] \arrow[rr, "", yshift=1ex] \ar[rr, phantom, "="{yshift=-0.25ex}] & & \Sh({\cal D}, K) \ar[ll, "", yshift=-1ex] \ar[d, "\Sh(\pi_{\cal D})", xshift=1ex]  \\
		\Sh((c_{F}\downarrow 1_{\cal D}), \overline{\tilde{K}})  \ar[u, "C_{\pi_{\cal D}'''}", xshift=-1ex] \ar[u, phantom, "\rotatebox{90}{$\sim$}"{xshift=0.25ex}]  \arrow[rr, "\Sh(w_{F})\cong C_{\pi_{(1_{\cal D}\downarrow F)}'}", yshift=1ex] \ar[rr, phantom, "\sim"{yshift=-0.25ex}]  \arrow[dr, "C_{\pi_{\cal C}'}"{below}]    & &  \Sh((1_{\cal D}\downarrow F), \tilde{K}) \ar[ll, "C_{w_{F}}\cong \Sh(\pi_{(1_{\cal D}\downarrow F)}') ", yshift=-1ex] \ar[u, "C_{\pi_{\cal D}}", xshift=-1ex ] \ar[u, phantom, "\rotatebox{90}{$\sim$}"{xshift=0.25ex}] \ar[ld, "C_{c_{F}}", yshift=0.5ex, xshift=-1ex]            \\
		& \Sh({\cal C}, J)  & 
		\end{tikzcd}
		\end{equation*}	 


		\item Let $G:({\cal D}, K) \to ({\cal C}, J)$ be a comorphism of sites, with corresponding morphism of sites $m_{G}:({\cal C}, J)\to (\hat{\cal D}, \hat{K})$ as in Theorem \ref{thmcomorphismtomorphism}. Let 
		\[
		z_{G}:(G\downarrow 1_{\cal C} )\to (1_{\hat{\cal D}}\downarrow m_{G})
		\]
		be the functor sending any object $(d,c, \alpha:G(d)\to c)$ of $(G\downarrow 1_{\cal C} )$ to the object $(y_{\cal D}(d), c, \overline{\alpha}:y_{\cal D}(d) \to m_{G}(c))$ of $(1_{\hat{\cal D}}\downarrow m_{G})$, where $\overline{\alpha}$ is the arrow corresponding to the element $\alpha$ of $m_{G}$ via the Yoneda Lemma. Then $z_{G}$ is both a (full and faithful) comorphism and a dense morphism of sites $((G\downarrow 1_{\cal C}), \overline{K} )\to ((1_{\hat{\cal D}}\downarrow m_{G}), \widetilde{\hat{K}})$ satisfying the relation $\pi_{\hat{\cal D}}\circ z_{G}=y_{\cal D}\circ \pi_{\cal D}'$ and inducing an equivalence relating $G$ and $m_{G}$, which makes the following diagram commute:
		\begin{equation*}
		\begin{tikzcd} 
		\Sh(\hat{\cal D}, \hat{K}) \ar[d, "\Sh(\pi_{\hat{\cal D}})", xshift=1ex] \arrow[rr, "\Sh(y_{\cal D})", yshift=1ex] \ar[rr, phantom, "\sim"{yshift=-0.25ex}] & & \Sh({\cal D}, K) \ar[ll, "C_{y_{\cal D}}", yshift=-1ex] \ar[d, "\Sh(\pi_{{\cal D}}')\cong C_{j_{G}}", xshift=1ex]  \\
		\Sh((1_{\hat{\cal D}}\downarrow m_{G}), \widetilde{\hat{K}}) \ar[u, "C_{\pi_{\hat{\cal D}}}", xshift=-1ex ] \ar[u, phantom, "\rotatebox{90}{$\sim$}"{xshift=0.25ex}] \arrow[rr, "\Sh(z_{G})", yshift=1ex] \ar[rr, phantom, "\sim"{yshift=-0.25ex}]  \arrow[dr, "C_{\pi_{\cal C}}\cong \Sh(i_{m_{G}})"{below, xshift=-5ex}]    & &  \Sh((G\downarrow 1_{\cal C}), \overline{K}) \ar[ll, "C_{z_{G}}", yshift=-1ex] \ar[u, "\Sh(j_{G})\cong C_{\pi_{{\cal D}'}}", xshift=-1ex ] \ar[u, phantom, "\rotatebox{90}{$\sim$}"{xshift=0.25ex}]  \ar[ld, "C_{\pi_{\cal C}'}", yshift=0.5ex, xshift=-1ex]            \\
		& \Sh({\cal C}, J)  & 
		\end{tikzcd}
		\end{equation*}	 
	\end{enumerate}

Let $({\cal C}, J)$ be a small-generated site. 
\begin{enumerate}[(a)]
	\item The category ${\textup{\bf Mor}}_{({\cal C}, J)}$ has as objects the morphisms of sites from $({\cal C}, J)$ to a small generated site $({\cal D}, K)$ and as arrows $$(F:({\cal C}, J)\to ({\cal D}, K))\to (F':({\cal C}, J)\to ({\cal D}', K'))$$ between any two such morphisms the geometric morphisms $$f:\Sh({\cal D}', K')\to \Sh({\cal D}, K)$$ such that $\Sh(F)\circ f\cong \Sh(F')$:

	\begin{equation*}
	\begin{tikzcd} 
	\Sh({\cal C}, J) & \Sh({\cal D}, K) \ar[l, "\Sh(F)"{above}]  \\
	& \Sh({\cal D}', K') \ar[u, "f"] \ar[ul, "\Sh(F')"] 
	\end{tikzcd}
	\end{equation*}	 

	\item The category ${\textup{\bf Coh}}_{({\cal C}, J)}$ has as objects the comorphisms of sites from a small-generated site $({\cal D}, K)$ to $({\cal C}, J)$ and as arrows
	$$(U:({\cal D}, K)\to ({\cal C}, J))\to (U':({\cal D}', K') \to ({\cal C}, J))$$ between any two such comorphisms the geometric morphisms $$g:\Sh({\cal D}, K)\to \Sh({\cal D}', K')$$ such that $C_{U'}\circ g\cong C_{U}$:

	\begin{equation*}
	\begin{tikzcd} 
	\Sh({\cal D}, K) \ar[d, "g"] \ar[r, "C_{U}"{above}]  & \Sh({\cal C}, J)   \\
	\Sh({\cal D}', K') \ar[ur, "\quad C_{U'}"{below}] &   
	\end{tikzcd}
	\end{equation*}	
\end{enumerate}

\label{adjointequivalencemorphismscomorphisms}
	The functors 
	\[
	C:	({\textup{\bf Mor}}_{({\cal C}, J)})^{\textup{op}} \to 	{\textup{\bf Coh}}_{({\cal C}, J)}
	\] 
	and
	\[
	M:	{\textup{\bf Coh}}_{({\cal C}, J)} \to 	({\textup{\bf Mor}}_{({\cal C}, J)})^{\textup{op}} 
	\]  
	are ($2$-categorically) adjoint ($C$ on the right and $M$ on the left) and quasi-inverse to each other.

\label{thmdualcommaconstruction}
	Let $F:({\cal D}, K)\to ({\cal C}, J)$ be a comorphism of small-generated sites, $i_{F}'$ the canonical functor ${\cal D}\to (1_{\cal C}\downarrow F)$ and $K^{i_{F}'}$ the Grothendieck topology on $(1_{\cal C}\downarrow F)$ coinduced by $K$ along $i_{F}'$ (in the sense of Proposition \ref{propimagetopology}). Let $\pi_{\cal C}^{F}$ and $\pi_{\cal D}^{F}$ be the canonical projections from $(1_{\cal C}\downarrow F)$ respectively to $\cal C$ and $\cal D$. Then 
	\begin{enumerate}[(i)]
		\item $\pi_{\cal D}^{F} \dashv i_{F}'$, $\pi_{\cal C}^{F}\circ i_{F}'=F$, $\pi_{\cal C}^{F}$ is a comorphism of sites $((1_{\cal C}\downarrow F), K^{i_{F}'}) \to ({\cal C}, J)$ and $\pi_{\cal D}^{F}$ is a comorphism of sites $((1_{\cal C}\downarrow F), K^{i_{F}'}) \to ({\cal D}, K)$;

		\item $i_{F}'$ is both a (full and faithful) comorphism of sites and a dense morphism of sites $({\cal D}, K) \to ((1_{\cal C}\downarrow F), K^{i_{F}'})$ inducing equivalences
		\[
		C_{i_{F}'}:\Sh({\cal D}, K) \to \Sh((1_{\cal C}\downarrow F), K^{i_{F}'})
		\]
		and
		\[
		\Sh(i_{F}'):\Sh((1_{\cal C}\downarrow F), K^{i_{F}'}) \to \Sh({\cal D}, K) 
		\]
		which are quasi-inverse to each other and make the following triangle commute:
		\begin{equation*}
		\begin{tikzcd}
		\Sh((1_{\cal C} \downarrow F), K^{i_{F}'}) \arrow[rr, "\Sh(i_{F}')\cong C_{\pi_{\cal D}^{F}}", yshift=1ex] \ar[rr, phantom, "\sim"{yshift=-0.25ex}]  \arrow[dr, "C_{{\pi_{\cal C}^{F}}}"{below, xshift=-2ex}]   & &  \Sh({\cal D}, K) \ar[ll, "C_{i_{F}'}", yshift=-1ex] \ar[ld, "C_{F}", yshift=0.5ex, xshift=-1ex]            \\
		& \Sh({\cal C}, J)  & 
		\end{tikzcd}
		\end{equation*}	

	\end{enumerate}

Let $i:{\cal F}\hookrightarrow {\cal E}$ be the geometric inclusion of a subtopos $\cal F$ of a Grothendieck topos $\cal E$ into $\cal E$, and let $f:{\cal G}\to {\cal E}$ be a weak morphism from a Grothendieck topos $\cal G$. Then the following conditions are equivalent:
\begin{enumerate}[(i)]
	\item The weak morphism $f$ factors through $i$; 

	\item The direct image $f_{\ast}$ takes values in $\cal F$ (that is, factors through $i_{\ast}$);

	\item The inverse image $f^{\ast}$ factors (necessarily uniquely up to isomorphism) through $i^{\ast}$.
\end{enumerate}

\label{corfact}
	Let $A:{\cal C}\to {\cal E}$ be a functor from an essentially small category $\cal C$ to a Grothendieck topos $\cal E$, and $J$ be a Grothendieck topology on $\cal C$. Then the following conditions are equivalent:
	\begin{enumerate}[(i)]
		\item The weak morphism $(L_{A} \dashv R_{A})$ factors through the canonical geometric inclusion $i:\Sh({\cal C}, J)\hookrightarrow [{\cal C}^{\textup{op}}, \Set]$; 

		\item The functor $R_{A}$ takes values in $\Sh({\cal C}, J)$;

		\item The functor $L_{A}$ factors (necessarily uniquely up to isomorphism) through the associated sheaf functor $a_{J}:[{\cal C}^{\textup{op}}, \Set]\to \Sh({\cal C}, J)$.
	\end{enumerate}

\label{defcanonicalfunctor}
	\begin{enumerate}[(a)]
		\item Given a small-generated site $({\cal C}, J)$, we say that a functor $A:{\cal C}\to {\cal E}$ is \emph{$J$-continuous} if the hom functor $R_{A}:{\cal E}\to [{\cal C}^{\textup{op}}, \Set]$ takes values into $\Sh({\cal C}, J)$ (equivalently, by Corollary \ref{corfact}, if the functor $L_{A}: [{\cal C}^{\textup{op}}, \Set]\to {\cal E}$ factors through $a_{J}:[{\cal C}^{\textup{op}}, \Set] \to \Sh({\cal C}, J)$). 

		\item Given small-generated sites $({\cal C}, J)$ and $({\cal D}, K)$, a functor $A:{\cal C}\to {\cal D}$ is said to be $(J, K)$-continuous if $l'\circ A$ is $J$-continuous, where $l'$ is the canonical functor ${\cal D}\to \Sh({\cal D}, K)$.
	\end{enumerate}

\label{propequivGroth}
	Let $({\cal C}, J)$ and $({\cal D}, K)$ be small-generated sites and  $A:{\cal C} \to {\cal D}$ a functor. Then the following conditions are equivalent:
\begin{enumerate}[(i)]
	\item $A$ is $(J, K)$-continuous.

	\item The functor $$D_{A}:=(-\circ A^{\textup{op}}):[{\cal D}^{\textup{op}}, \Set]\to [{\cal C}^{\textup{op}}, \Set]$$ restricts to a functor $\Sh({\cal D}, K) \to \Sh({\cal C}, J)$.	
	\end{enumerate}

\label{examplemorphismsofdiscretefibrations}
	Let $P$ and $Q$ be presheaves on a category $\cal C$. Then, for any morphism $\alpha:P\to Q$, the comorphism of sites  ${\int \alpha}:({\int P}, J_{P})\to ({\int Q}, J_{Q})$ is $(J_{P}, J_{Q})$-continuous (where $J_{P}$ and $J_{Q}$ are the Grothendieck topologies defined in Remark \ref{remrelativetopology}). Indeed, this follows from Proposition \ref{propequivGroth} by observing that the functor $D_{\int \alpha}:=(-\circ {(\int \alpha)}^{\textup{op}}):[{(\int Q)}^{\textup{op}}, \Set]\to [{(\int P)}^{\textup{op}}, \Set]$ restricts to a functor $\Sh({\int Q}, J_{Q}) \to \Sh({\int P}, J_{P})$. In particular, all the comorphisms of the form $\pi_{P}:({\int P}, J_{P}) \to ({\cal C}, J)$ are $(J_{P}, J)$-continuous. Alternatively, the continuity of ${\int \alpha}:({\int P}, J_{P})\to ({\int Q}, J_{Q})$ follows from Corollary \ref{correstrictioncomorphism} below by observing that the geometric morphism $\Sh({\cal C}, J)\slash a_{J}(\alpha):\Sh({\cal C}, J)\slash a_{J}(P)\to \Sh({\cal C}, J)\slash a_{J}(Q)$ induced by the arrow $a_{J}(\alpha):a_{J}(P)\to a_{J}(Q)$ is essential and the following diagram, where $Z_{a_{J}(h)}$ is the functor $\Sh({\cal C}, J)\slash a_{J}(P)\to \Sh({\cal C}, J)\slash a_{J}(Q)$ given by composition with $a_{J}(\alpha)$ (that is, the essential image of $\Sh({\cal C}, J)\slash a_{J}(\alpha)$) and the vertical functors are the canonical ones modulo the equivalences of section \ref{sec:example}, commutes: 

	$$
	\xymatrix{
		{\int P} \ar[r]^{\int \alpha} \ar[d] & {\int Q} \ar[d] \\
		\Sh({\cal C}, J)\slash a_{J}(P) \ar[r]^{Z_{a_{J}(h)}} & \Sh({\cal C}, J)\slash a_{J}(Q)
	}
	$$ 

	See also Theorem \ref{thmlocallyconnected} below.

\label{propcharcanonicalfunctors}
	Let $({\cal C}, J)$ and $({\cal D}, K)$ be small-generated sites. Then a functor $A:{\cal C}\to {\cal D}$ is $(J, K)$-continuous if and only if it is cover-preserving (i.e., sends $J$-covering families to $K$-covering ones) and for any $J$-covering sieve $S$ on an object $c$ and any commutative square of the form
	\[
	\xymatrix{
		d \ar[r] \ar[d]  & A(c') \ar[d]^{A(f)} \\
		A(c'') \ar[r]^{A(g)} & A(c),
	} 
	\]	
	where $f:c'\to c$ and $g:c''\to c$ are arbitrary arrows of $S$, there is a $K$-covering family $\{d_{i}\to d \mid i\in I\}$ such that for each $i\in I$, the composites $d_{i}\to A(c')$ and $d_{i}\to A(c'')$ belong to the same connected component of the category $(d_{i}\downarrow D^{A}_{S})$.

Let $({\cal C},J)$ and $({\cal D}, K)$ be small-generated subcanonical sites and $g:\Sh({\cal C},J) \to \Sh({\cal D}, K)$ be a geometric morphism induced by a morphism of sites $G:({\cal D}, K) \to ({\cal C},J)$. Then the following conditions are equivalent:
\begin{enumerate}[(i)]
	\item $g$ is essential and its essential image restricts to the representables; 

	\item $G:{\cal D}\to {\cal C}$ has a left adjoint $F:{\cal C}\to {\cal D}$ which is $(J, K)$-continuous. 
\end{enumerate}

\label{proppresheaflifting}
Any comorphism of sites $f:({\cal C}, J)\to ({\cal C}', J')$ extends to a comorphism of sites $\hat{f}:([{\cal C}^{\textup{op}}, \Set], \hat{J}) \to ([{\cal C}'^{\textup{op}}, \Set], \hat{J'})$ given by the left Kan extension along $f^{\textup{op}}$, and the following diagram commutes:
\[
\xymatrix{
	\Sh({\cal C}, J)  \ar[r] \ar[d]_{C_{f}} & \Sh([{\cal C}^{\textup{op}}, \Set], \hat{J}) \ar[d]^{C_{\hat{f}}} \\
	\Sh({\cal C}', J')  \ar[r] & \Sh([{{\cal C}'}^{\textup{op}}, \Set], \hat{J'})
} 
\]

\label{propliftcontinuity}
	Let $A:({\cal C}, J)\to ({\cal D}, K)$, $B:({\cal C}, J) \to ({\cal E}, L)$ and $C:({\cal D}, K)\to ({\cal E}, L)$ be comorphisms of sites related by a natural isomorphism $C\circ A\cong B$. If $B$ is $(J, L)$-continuous and $C$ is a fibration then $A$ satisfies the conditions of Proposition \ref{propcharcanonicalfunctors} with respect to every $J$-covering sieve $S$ which satisfies the property that there is a functorial factorization $g=g_{c}\circ g_{v}$ for any arrow $g$ in $S$ such that $g_{c}$ lies in $S$, $A(g_{c})$ is a cartesian arrow and $A(g_{v})$ is a vertical arrow (whence the factorization $A(g)=A(g_{c})\circ A(g_{v})$ yields ` the' decomposition of $A(g)$ in $\cal D$ as a vertical arrow followed by a cartesian arrow); that is, for any such sieve $S$ on an object $c$, $A(S)$ is $K$-covering and for any commutative square of the form
	\[
	\xymatrix{
		d \ar[r] \ar[d]  & A(c') \ar[d]^{A(f)} \\
		A(c'') \ar[r]^{A(g)} & A(c),
	} 
	\]	
	where $f:c'\to c$ and $g:c''\to c$ are arbitrary arrows of $S$, there is a $K$-covering family $\{d_{i}\to d \mid i\in I\}$ such that for each $i\in I$, the composites $d_{i}\to A(c')$ and $d_{i}\to A(c'')$ belong to the same connected component of the category $(d_{i}\downarrow D^{A}_{S})$.

\label{remlocallyconnectedcondition}
Recall that every \emph{local homeomorphism} (that is, geometric morphism of the form $U^{\cal E}_{E}:{\cal E}\slash E\to {\cal E}$ for some object $E$ of a topos $\cal E$) is locally connected. Notice that, for any arrow $u:E'\to E$ in a topos $\cal E$, the geometric morphism $U^{\cal E}_{u}:{\cal E}\slash E'\to {\cal E}\slash E$ induced by it (whose inverse image is given by the pullback functor along $u$) is a local homeomorphism (since it can be identified with the functor $U^{{\cal E}\slash B}_{[u:E'\to E]}$). Let us denote by $\Sigma^{\cal E}_{u}$ the essential image of $U^{\cal E}_{u}$, that is, the functor ${\cal E}\slash E'\to {\cal E}\slash E$ acting as composition with $u$.  Given an arrow $h:[a:A\to E]\to [b:B\to E]$ in ${\cal E}\slash E$, that is an arrow $h:A\to B$ in $\cal E$ such that $b\circ h=a$, condition $\Gamma^{U^{\cal E}_{u}}_{h}$ rewrites as follows: given pullback squares
$$
\xymatrix {
	A' \ar[d]^{a'} \ar[r]^{u_{A}} &  A \ar[d]^{a} & \textup{ and } & B' \ar[d]^{b'} \ar[r]^{u_{B}} &  B \ar[d]^{b} \\ 
	E' \ar[r]^{u}  & E & &
	E' \ar[r]^{u} & E,}
$$
the diagram	
\[
\xymatrix{
	{\cal E}\slash B' \ar[rr]^{\Sigma^{\cal E}_{u_{B}}} \ar[d]^{(u^{\ast}(h))^{\ast}} & &  {\cal E}\slash B    \ar[d]^{h^{\ast}} \\
	{\cal E}\slash A' \ar[rr]^{\Sigma^{\cal E}_{u_{A}}} & & {\cal E}\slash A
} 
\]
commutes. In the case $b=1_{E}$, the arrow $h$ is simply an arrow $a:A\to E$ and this square specializes to the following one:
\[
\xymatrix{
	{\cal E}\slash E' \ar[rr]^{\Sigma^{\cal E}_{u}} \ar[d]^{(u^{\ast}(a))^{\ast}} & &  {\cal E}\slash E    \ar[d]^{a^{\ast}} \\
	{\cal E}\slash A' \ar[rr]^{\Sigma^{\cal E}_{u_{A}}} & & {\cal E}\slash A.
} 
\]

\label{propsimplificationlocallyconnected}
	Let  $f:{\cal F}\to {\cal E}$ be an essential geometric morphism between Grothendieck toposes and $h:A\to B$ an arrow of $\cal E$.
	\begin{enumerate}[(i)]
		\item For any epimorphic family $\{f_{i}:A_{i}\to A \mid i\in I\}$ in $\cal E$, $\Gamma^{f}_{h}$ holds if and only if $\Gamma^{f}_{h\circ f_{i}}$ holds for every $i\in I$.

		\item For any epimorphic family $\{g_{j}:B_{j}\to B \mid j\in J\}$ in $\cal E$, $\Gamma^{f}_{h}$ holds if and only if $\Gamma^{f}_{g_{j}^{\ast}(h)}$ holds for every $j\in J$.
	\end{enumerate}

\label{lemmaslicetoposclassification}
	Let $A$ be an object of a topos $\cal E$. Then, for any topos $\cal F$, the geometric morphisms $g:{\cal F}\to {\cal E}\slash A$ correspond bijectively to the pairs $(f, \alpha)$, where $f$ is a geometric morphism ${\cal F}\to {\cal E}$ and $\alpha$ is an arrow $1_{\cal F}\to f^{\ast}(A)$ in $\cal F$ (naturally in $A$ and $\cal F$). More specifically:	
	\begin{itemize}
		\item given a geometric morphism $g:{\cal F}\to {\cal E}\slash A$, the pair associated with it is $(U_{A}\circ g, \alpha_{g})$, where $\alpha_{g}:1_{\cal F}\to g^{\ast}(U_{A}^{\ast}(A))$ is the arrow $g^{\ast}(\Delta_{A})$, where $\Delta_{A}:1_{{\cal E}\slash A}\to U_{A}^{\ast}(A)$ is the arrow given by the diagonal $A\to A\times A$ on the object $A$; 

		\item given a pair $(f, \alpha)$ consisting of a geometric morphism $f:{\cal F}\to {\cal E}$ and an arrow $\alpha:1_{\cal F} \to f^{\ast}(A)$, the geometric morphism $f_{\alpha}:{\cal F}\to {\cal E}\slash A$ corresponding to the pair $(f, \alpha)$ is defined by setting, for any object $[x:X\to A]$ of ${\cal E}\slash A$, $f_{\alpha}^{\ast}([x])\mono f^{\ast}(X)$ equal to the equalizer of the arrows $\alpha\circ !_{f^{\ast}(X)}$ and $f^{\ast}(x)$ (where $!_{f^{\ast}(X)}$ is the unique arrow $f^{\ast}(X)\to 1_{\cal F}$).
	\end{itemize}

\label{proporthogonality}
Terminally connected morphisms are orthogonal to local homeomorphisms
in the $2$-category of Grothendieck toposes; that is, for any commutative square
\begin{equation*}
\begin{tikzcd}
{\cal F} \arrow[rr, "f"]   \arrow[d, "m"]   & &  {\cal E} \arrow[d, "n"] \arrow[dll, dashed, "k"{above}]  \\
{\cal G} \ar[rr, "g"] & & {\cal H},   
\end{tikzcd}
\end{equation*}	
where $f$ is terminally connected and $g$ is a local homeomorphism, there exists a morphism $k:{\cal E}\to {\cal G}$ (unique up
to unique $2$-isomorphism) making both triangles commute.

Let $F:{\cal C}\to {\cal D}$ be a functor and $K$ a Grothendieck topology  on $\cal D$. The \emph{$K$-comprehensive factorization of $F$} is given by the composite $F_{K}\circ \xi^{F}_{K}$:
\begin{equation*}
\begin{tikzcd}
{\cal C} \arrow[rr, "F"]   \arrow[dr, "\xi^{F}_{K}"]   & &  {\cal D}           \\
&  \int F_{K} \ar[ur, "\pi_{F_{K}}"] &  
\end{tikzcd}
\end{equation*}

\label{proporthogonality}
	The following orthogonality property of cofinal functors with respect of glueing fibrations (along continuous functors) holds: for any commutative square
	\begin{equation*}
	\begin{tikzcd}
	{\cal A} \arrow[rr, "F"]   \arrow[d, "u"]   & &  {\cal C} \arrow[d, "v"] \arrow[dll, dashed, "G"{above}]  \\
	{\cal B} \ar[rr, "p"] & & {\cal C}'   
	\end{tikzcd}
	\end{equation*}	
	where $\cal C$ and ${\cal C}'$ are respectively endowed with Grothendieck topologies $J$ and $J'$ such that $v$ is $(J, J')$-continuous, $F$ is $J$-cofinal and $p$ is a $J'$-glueing discrete fibration, there is a unique (up to isomorphism) functor $G:{\cal C}\to {\cal B}$ which makes both triangles commute (up to isomorphism).

A morphism of sites $F:({\cal C}, J)\to ({\cal D}, K)$ is said to be \emph{dense} if it satisfies the following properties:
\begin{enumerate}[(i)]	
	\item $P$ is a $J$-covering family in $\cal C$ if and only if $F(P)$ is a $K$-covering family in $\cal D$;
	\item $F$ is \emph{$K$-dense} in the sense that for any object $d$ of $\cal D$ there exists a $K$-covering family of arrows $d_{i}\to d$ whose domains $d_{i}$ are in the image of $F$;
	\item for every $c_{1}, c_{2}\in {\cal C}$ and any arrow $g:F(c_{1})\to F(c_{2})$ in $\cal D$, there exist a $J$-covering family of arrows $f_{i}:c'_{i}\to c_{1}$ and a family of arrows $k_{i}:c'_{i}\to c_{2}$ such that $g\circ F(f_{i})=F(k_{i})$ for all $i$.
\end{enumerate}

\label{remmorphismsofsitesfaithfulness}
	This definition is adapted from section 11 of \cite{Shulman}, where a functor $F:{\cal C}\to {\cal D}$ is defined to be a dense morphism of sites if it satisfes the three conditions above plus the following one (which we shall call $J$-faithfulness in section \ref{sec:localconditions}): 
	\begin{enumerate}[(i)]
	\item[(iv)] for any arrows $f_{1}, f_{2}:c_{1}\to c_{2}$ in $\cal C$ such that $F(f_1)=F(f_2)$ there exists a $J$-covering family of arrows $k_{i}:c'_{i}\to c_{1}$ such that $f_1 \circ k_{i}=f_{2}\circ k_{i}$ for all $i$. 
    \end{enumerate}
	In fact, Theorem 11.2 \cite{Shulman}(b) proves that every such functor $F$ is a morphism of sites $({\cal C}, J)\to ({\cal D}, K)$. On the other hand, if $F$ is already a morphism of sites, condition (iv) is unnecessary as it is implied by condition (i) (cf. condition (iv) in Definition \ref{defmorphismsites}).

\label{propweaklydensemorphism}
	Let $F:({\cal C}, J)\to ({\cal D}, K)$ be a morphism of sites. Then $F$ is a weakly dense morphism of sites if and only if it satisfies the following conditions:
	\begin{enumerate}[(i)]
	\item $P$ is a $J$-covering family in $\cal C$ if and only if $F(P)$ is a $K$-covering family in $\cal D$;

    \item for any object $d$ of $\cal D$ there exist a family $\{S_{i} \mid i\in I\}$ of $K$-covering sieves on objects of the form $F(c_{i})$ (where $c_{i}$ is an object of $\cal C$) and for each $f\in S_{i}$ an arrow $g_{f}:\textup{dom}(f)\to d$ such that $g_{f\circ z}\equiv_{K} g_{f}\circ z$ whenever $z$ is composable with $f$, such that the family of arrows $g_{f}$ (for $f\in S_{i}$ for some $i$) is $K$-covering;  

    \item for any objects $x, y$ of ${\cal C}$ and any family of arrows $g_{h}:\textup{dom}(h)\to F(y)$ indexed by the arrows of a $K$-covering sieve $U$ on $F(x)$ such that $g_{h\circ k}\equiv_{K} g_{h}\circ k$ for every arrow $k$ composable with $h$, there exist a $J$-covering family of arrows $\{f_{i}:x_{i}\to x \mid  i\in I\}$ and arrows $k_{i}:x_{i}\to y$ (for each $i\in I$) such that for every arrows $w$ and $z$ such that $F(f_{i})\circ w=h\circ z$, we have $g_{h}\circ z\equiv_{K} F(k_{i})\circ w$ (for every $h\in U$ and $i\in I$).
	\end{enumerate}

\label{exampleweaklydensenotdense}
Let us discuss an example of a weakly dense morphism of sites which is not dense.
Let $\bf{2}$ be the preorder category with two distinct objects $0$ and $1$ and just one arrow $0\to 1$ apart from the identities. Notice that $\bf{2}$ is cartesian, since it is a meet-semilattice, and the functor $F:\bf{2}\to \bf{2}$ sending $0$ to $1$, $1$ to $1$ and the arrow $0\to 1$ to the identity arrow on $1$ is cartesian as it is a meet-semilattice homomorphism. Let us equip $\bf{2}$ with the atomic topology $J_{\textup{at}}$, whose covering sieves are the maximal ones plus the sieve on $1$ consisting of the arrow $0\to 1$. Since it is cartesian and cover-preserving, the functor $F$ is a morphism of sites $({\mathbf{2}}, J_{\textup{at}})\to ({\mathbf{2}}, J_{\textup{at}})$. Now, by the Comparison Lemma, the topos $\Sh({\mathbf{2}}, J_{\textup{at}})$ is equivalent to the topos of sheaves on the one-object full subcategory $\{0\}$ of $\bf{2}$ with respect to the induced topology on it, namely the maximal one; so we have $\Sh({\mathbf{2}}, J_{\textup{at}})\simeq \Set$. Therefore the geometric morphism $\Sh(F):\Sh({\mathbf{2}}, J_{\textup{at}}) \to \Sh({\mathbf{2}}, J_{\textup{at}})$ is necessarily (isomorphic) to the identity morphism (since the only geometric morphism $\Set \to \Set$ is the identity one); in particular, it is an equivalence. Therefore, by Theorem \ref{thmweakdensityequivalence}, $F$ is a weakly dense morphism of sites. However, $F$ is \emph{not} dense; for instance, it does not satisfy condition (ii) in the definition of a dense morphism of sites. Indeed, there is no $J_{\textup{at}}$-covering family of arrows to the object $0$ whose domain is in the image of the functor $F$. On the other hand, it satisfies condition (ii) in the characterization of weakly dense morphisms of sites provided by Proposition \ref{propweaklydensemorphism}. Indeed, if $d=1$ then the arrow $k=1_{1}$ satisfies the condition (by taking $h=1_{1}$, $x=0$ or $x=1$, $S=\{0\to 1\}$ and $g_{0\to 1}=0\to 1$), while if $d=0$ then the arrow $k=1_{0}$ satisfies the condition (by taking $h=0\to 1$, $x=0$ or $x=1$, $S=\{0\to 1\}$ and $g_{0\to 1}=1_{0}$).

\label{flatequivalence}
	Let $({\cal C}, J)$ be a small-generated site, $\cal E$ a Grothendieck topos and $F:{\cal C}\to {\cal E}$ a $J$-continuous flat functor. Then the geometric morphism $f:{\cal E}\to \Sh({\cal C}, J)$ induced by $F$ is an equivalence if and only if $F$ satisfies the following conditions:
		\begin{enumerate}[(i)]	
			\item If the image under $F$ of a sieve $S$ in $\cal C$ is epimorphic in $\cal E$ then $S$ is $J$-covering;
			\item the family of objects of the form $F(c)$ for $c\in {\cal C}$ is separating for $\cal E$;
			\item for every $x, y\in {\cal C}$ and any arrow $g:F(x)\to F(y)$ in $\cal E$, there exist a $J$-covering family of arrows $f_{i}:x_{i}\to x$ and a family of arrows $g_{i}:x_{i}\to y$ such that $g\circ F(f_{i})=F(g_{i})$ for all $i$.			
		\end{enumerate}

Let $({\cal C}, J)$ and $({\cal D}, K)$ be two small-generated sites. Then the following conditions are equivalent:

\begin{enumerate}[(i)]
	\item The toposes $\Sh({\cal C}, J)$ and $\Sh({\cal D}, K)$ are equivalent.

	\item There exist a category (resp. an essentially small category, if $\cal C$ and $\cal D$ are essentially small) $\cal A$, a Grothendieck topology $Z$ on $\cal A$ (which can be supposed subcanonical) and two functors $H:{\cal C}\to {\cal A}$ and $K:{\cal D}\to {\cal A}$ satisfying the following conditions:
	\begin{enumerate}[(i)]	
	\item $P$ is a $J$-covering family in $\cal C$ if and only if $H(P)$ is a $Z$-covering family in $\cal A$;
	\item $Q$ is a $K$-covering family in $\cal D$ if and only if $K(Q)$ is a $Z$-covering family in $\cal A$;
	\item for any object $a$ of $\cal A$ there exists a $Z$-covering sieve whose arrows factor both through an arrow whose domain is in the image of $H$ and through an arrow whose domain is in the image of $K$;
	\item for every $x, y\in {\cal C}$ (resp. $x',y'\in {\cal D}$) and any arrow $g:H(x)\to H(y)$ (resp. $g':K(x')\to K(y')$) in $\cal A$, there exist a $J$-covering family of arrows $f_{i}:x_{i}\to x$ (resp. a $K$-covering family of arrows $f_{j}':x_{j}'\to x'$) and a family of arrows $g_{i}:x_{i}\to y$ (resp. a family of arrows $g'_{j}:x_{j}'\to y'$) such that $g\circ H(f_{i})=H(g_{i})$ for all $i$ (resp. $g'\circ K(f_{j}')=K(g'_{j})$ for all $j$);
	\item for any arrows $h, k:x\to y$ (resp. $h',k':x'\to y'$) in $\cal C$ (resp. in $\cal D$) such that $H(h)=H(k)$ (resp. $K(h')=K'(k')$) there exists a $J$-covering (resp. $K$-covering) family of arrows $f_{i}:x_{i}\to x$ (resp. $f'_{j}:x'_{j}\to x'$) such that $h\circ f_{i}=k\circ f_{i}$ for all $i$ (resp. $h'\circ f'_{j}=k'\circ f'_{j}$ for all $j$). 
	\end{enumerate}		 

\end{enumerate}

\label{proplocalproperties}
	Let $F:({\cal C}, J)\to ({\cal D}, K)$ be a morphism of sites. Then

	\begin{enumerate}[(i)]
		\item $F$ is $(J, K)$-faithful if and only if $a_{F}$ is faithful;

		\item If $F$ is $(J, K)$-faithful and satisfies the covering-lifting property then $F$ is $(J, K)$-full if and only if $a_{F}$ is full;

		\item If $F$ satisfies the covering-lifting property then $F$ is $K$-dense if and only if $a_{F}$ is $C^{\cal D}_{K}$-dense. 
	\end{enumerate}

\label{corequivalencecovliftproperty}
	Let $F$ be a morphism of sites $({\cal C}, J)\to ({\cal D}, K)$. Then the following conditions are equivalent:
	\begin{enumerate}[(i)]
		\item $F$ is a weakly dense morphism of sites which has the covering-lifting property;

		\item $F$ is dense (that is, $K$-dense, $J$-full and cover-reflecting).
	\end{enumerate}

\label{corinterpretationsfaithful}
\begin{enumerate}[(i)]
	\item An intepretation $I:{\cal C}_{\mathbb T}\to {\cal C}_{\mathbb S}$ between geometric theories $\mathbb T$ and $\mathbb S$ induces a geometric surjection $\Set[{\mathbb S}]\to \Set[{\mathbb T}]$ between their classifying toposes if and only if, with the above notation, for every sequent $\sigma$ over the signature of $\mathbb T$, if the sequent $I(\sigma)$ is provable in $\mathbb S$ then $\sigma$ is provable in $\mathbb T$. 

	\item In particular, if $I$ is the canonical interpretation given by an expansion ${\mathbb T}'$ of ${\mathbb T}$ (in the sense of section 7.1 of \cite{OCBook}) then $I$ induces a geometric surjection if and only if ${\mathbb T}'$ is a \emph{conservative expansion} of $\mathbb T$, that is, every geometric sequent over the signature of $\mathbb T$ which is provable in ${\mathbb T}'$ is provable in ${\mathbb T}$.
\end{enumerate}

\label{Morphismsmaalgenerated}
	Let $F:({\cal C}, J)\to ({\cal D}, K)$ be a morphism of small-generated sites. Then:

	\begin{enumerate}[(i)]
		\item The geometric morphism $\Sh(F):\Sh({\cal D}, K) \to \Sh({\cal C}, J)$ induced by $F$ is a surjection if and only if $F$ is \emph{cover-reflecting} (that is, if the image of a family of arrows with a fixed codomain is $K$-covering then the family is $J$-covering).

		\item The surjection-inclusion factorization of the geometric morphism $\Sh(F):\Sh({\cal D}, K) \to \Sh({\cal C}, J)$ induced by $F$ can be identified with the factorization $\Sh(i_{J_{F}})\circ \Sh(F_{r})$, 
		where $J_{F}$ is the Grothendieck topology on $\cal C$ whose covering sieves are exactly those whose image under $F$ are $K$-covering families, $i_{J_{F}}:({\cal C}, J)\to ({\cal C}, J_{F})$ is the morphism of sites given by the canonical inclusion functor and $F_{r}: ({\cal C}, J_{F}) \to ({\cal D}, K)$ is the morphism of sites given by $F$. 

		\item The geometric morphism $\Sh(F):\Sh({\cal D}, K) \to \Sh({\cal C}, J)$ induced by $F$ is an inclusion if and only if $F_{r}: ({\cal C}, J_{F}) \to ({\cal D}, K)$ is a weakly dense morphism of sites (equivalently, if $K$ is subcanonical, a dense morphism of sites); in particular, if $K$ is subcanonical then $\Sh(F)$ is an inclusion if and only if the following conditions are satisfied:

		\begin{enumerate}[(i)]	
			\item for any object $d$ of $\cal D$ there exists a $K$-covering family of arrows $d_{i}\to d$ whose domains $d_{i}$ are in the image of $F$;
			\item for every $x, y\in {\cal C}$ and any arrow $g:F(x)\to F(y)$ in $\cal D$, there exist a $J_{F}$-covering family of arrows $f_{i}:x_{i}\to x$ and a family of arrows $g_{i}:x_{i}\to y$ such that $g\circ F(f_{i})=F(g_{i})$ for all $i$.
		\end{enumerate}
	\end{enumerate}

\label{corinclusionflatfunctor}
	A $J$-continuous flat  functor $F:{\cal C} \to {\cal E}$ induces a geometric inclusion if and only if it satisfies the following conditions:  
	\begin{enumerate}[(i)]	
		\item every object of $\cal E$ can be covered by objects which are in the image of $F$;
		\item for every $x, y\in {\cal C}$ and any arrow $g:F(x)\to F(y)$ in $\cal E$, there exist a family of arrows $f_{i}:x_{i}\to x$ which is sent by $F$ to an epimorphic family and a family of arrows $g_{i}:x_{i}\to y$ such that $g\circ F(f_{i})=F(g_{i})$ for all $i$.
	\end{enumerate}

\label{propimagetopology}
	Let $F:{\cal C}\to {\cal D}$ be a functor and $J$ a Grothendieck topology on $\cal C$. Then there is a Grothendieck topology $J^{F}$ on $\cal D$, called the \emph{image of $J$ along $F$} (or the Grothendieck topology \emph{coinduced} by $J$ along $F$), such that for any sieve $T$ on an object $d$ of $\cal D$, $T\in J^{F}(d)$ if and only if for any object $c\in {\cal C}$ and any arrow $\xi:F(c)\to d$ in $\cal D$, there exists a $J$-covering sieve $R$ on $c$ such that $F(R)\subseteq \xi^{\ast}(T)$. Then the functor $F:({\cal C}, J)\to ({\cal D}, J^{F})$ is $J^{F}$-dense and has the covering-lifting property.

	The Grothendieck topology $J^{F}$ enjoys the following universal property: the subtopos $\Sh({\cal D}, J^{F})\hookrightarrow [{\cal D}^{\textup{op}}, \Set]$ is the image (in the sense of surjection-inclusion factorization) of the composite of the induced geometric morphism $[F^{\textup{op}}, \Set]:[{\cal C}^{\textup{op}}, \Set]\to [{\cal D}^{\textup{op}}, \Set]$ with the subtopos inclusion $\Sh({\cal C}, J)\hookrightarrow [{\cal C}^{\textup{op}}, \Set]$.

\label{lemmafullfaithfulcoverreflecting}
Let $F:{\cal C}\to {\cal D}$ be a $J$-full and $J$-faithful functor, for a Grothendieck topology $J$ on $\cal C$. Then:
\begin{enumerate}[(i)]
	\item for any sieve $R$ on an object $c$ of $\cal C$ and any arrow $t$ with codomain $c$, if $F(t)$ belongs to the sieve generated by $F(R)$ then there exists a $J$-covering sieve $U$ on $\textup{dom}(t)$ such that $t\circ u\in R$ for each $u\in U$;  

	\item the functor $F:({\cal C}, J)\to ({\cal D}, J^{F})$ is cover-reflecting.
\end{enumerate}

\label{corinclusionequivalence}
	Let $f:{\cal F}\to {\cal E}$ be a geometric morphism. Then 

	\begin{enumerate}[(i)]
	\item $f$ is an inclusion if and only if $f^{\ast}$ satisfies the following conditions:


		\begin{enumerate}[(i)]	
			\item \textup{$f^{\ast}$ is locally surjective}, that is every object of $\cal F$ can be covered by objects in the image of $f^{\ast}$;

			\item \textup{$f^{\ast}$ is locally full}, that is for every $x, y\in {\cal E}$ and any arrow $g:f^{\ast}(x)\to f^{\ast}(y)$ in $\cal F$, there exists a family of arrows $s_{i}:x_{i}\to x$ in $\cal E$ which is sent by $f^{\ast}$ to an epimorphic family and a family of arrows $g_{i}:x_{i}\to y$ such that $g\circ f^{\ast}(s_{i})=f^{\ast}(g_{i})$ for all $i$.
		\end{enumerate}

	\item $f$ is an equivalence if and only if $f^{\ast}$ is faithful, locally full and locally surjective.

	\end{enumerate}

\label{remsurjectionsinclusions}
	Since a Grothendieck topos has all coproducts, all the covering families arising in the formulations of the properties in part (i) of Corollary \ref{corinclusionequivalence} can be supposed, without loss of generality, to consist of a single element. More precisely, the condition for $f$ to be an inclusion is equivalent to the conjunction of the following ones:  
		\begin{enumerate}[(i)]	
			\item every object of $\cal F$ is a quotient of an object in the image of $f^{\ast}$;

			\item for every $x, y\in {\cal E}$ and any arrow $g:f^{\ast}(x)\to f^{\ast}(y)$ in $\cal F$, there exist an arrow $s:x'\to x$ in $\cal E$ which is sent by $f^{\ast}$ to an epimorphism and an arrow $g':x'\to y$ such that $g\circ f^{\ast}(s)=f^{\ast}(g')$.
		\end{enumerate}

		So, $f$ is an equivalence if and only if $f^{\ast}$ is faithful and satisfies the above conditions.

\label{exgeometricinclusion}
	Let $f:{\cal F}\to {\cal E}$ be a geometric morphism between Grothendieck toposes and $A$ an object of $\cal E$. Then we have a geometric morphism $f_{A}:{\cal F}\slash f^{\ast}(A)\to {\cal E}\slash A$ such that the diagram
	$$
	\xymatrix{
		{\cal F}\slash f^{\ast}(A)  \ar[r] \ar[d]_{f_{A}} & {\cal F} \ar[d]^{f} \\
		{\cal E}\slash A \ar[r] & {\cal E}
	} 
	$$  
	where the horizontal morphisms are the canonical ones, commutes. The inverse image of $f_{A}$ is the functor ${\cal E}\slash A \to {\cal F}\slash f^{\ast}(A)$ sending an object $u:B\to A$ of ${\cal E}\slash A$ to $f^{\ast}(u):f^{\ast}(B)\to f^{\ast}(A)$ (and acting accordingly on arrows). Let us show, by applying Corollary \ref{corinclusionequivalence}(i), that if $f$ is an inclusion then $f_{A}$ is also an inclusion. First, let us show that ${f_{A}}^{\ast}$ is locally surjective. Given an object $u:C\to f^{\ast}(A)$ of ${\cal F}\slash f^{\ast}(A)$, since $f^{\ast}$ is locally surjective there is an object $B$ of $\cal E$ and an epimorphism $q:f^{\ast}(B)\to C$. Consider the composite arrow $u\circ q:f^{\ast}(B)\to f^{\ast}(A)$. Since $f^{\ast}$ satisfies condition (ii) of Corollary \ref{corinclusionequivalence}(i), there is an arrow $s:B'\to B$ in $\cal E$ and an arrow $g:B'\to A$ in $\cal E$ such that $f^{\ast}(s)$ is an epimorphism and $u\circ q\circ f^{\ast}(s)=f^{\ast}(g)$ (cf. Remark \ref{remsurjectionsinclusions}). Therefore the arrow $q\circ f^{\ast}(s)$ is an epimorphism from ${f_{A}}^{\ast}(g)$ to $u$ in ${\cal F}\slash f^{\ast}(A)$. The fact that ${f_{A}}^{\ast}$ inherits local fullness from $f^{\ast}$ is obvious.

\label{corsyntactichyperconnected}
An interpretation $I:{\cal C}_{\mathbb T}\to {\cal C}_{\mathbb S}$ between geometric theories $\mathbb T$ and $\mathbb S$ induces an hyperconnected geometric morphism $\Set[{\mathbb S}]\to \Set[{\mathbb T}]$ if and only if for every sequent $\sigma$ over the signature of $\mathbb T$, if the sequent $I(\sigma)$ is provable in $\mathbb S$ then $\sigma$ is provable in $\mathbb T$, and for any sorts $A_{1}, \ldots, A_{n}$ of the signature of $\mathbb T$, every geometric formula $\psi$ over the signature of $\mathbb S$ in the context $I((x_{1}^{A_{1}}, \ldots, x_{n}^{A_{n}}))$ is $\mathbb T$-provably equivalent (in its context) to a formula $I(\phi)$, where $\phi$ is a geometric formula over the signature of $\mathbb T$ in the context $(x_{1}^{A_{1}}, \ldots, x_{n}^{A_{n}})$. 	

In particular, if $I$ is the canonical interpretation given by an expansion ${\mathbb T}'$ of ${\mathbb T}$ (in the sense of section 7.1 of \cite{OCBook}) then the geometric morphism induced by $I$ is hyperconnected if and only if every sequent over the signature of $\mathbb T$ which is provable in ${\mathbb T}'$ is provable in $\mathbb T$, and for any sorts $A_{1}, \ldots, A_{n}$ of the signature of $\mathbb T$, every geometric formula $\psi$ in the context $(x_{1}^{A_{1}}, \ldots, x_{n}^{A_{n}})$ over the signature of ${\mathbb T}'$ is $\mathbb T$-provably equivalent (in its context) to a geometric formula over the signature of $\mathbb T$.

\label{thmhyperconnectedlocalicfactorization}
	Let $F:({\cal C}, J)\to ({\cal D}, K)$ be a morphism of small-generated sites. Then the hyperconnected-localic factorization of the geometric morphism $\Sh(F)\circ \Sh(i_{K}^{s}):\Sh({\cal D}_{K}^{s}, C_{K}^{s})\simeq \Sh({\cal D}, K) \to \Sh({\cal C}, J)$ induced by $F$ can be identified with the factorization $\Sh(F^{s})\circ \Sh(i_{F}^{s})$, where
	${\cal D}_{F}^{s}$ is the full subcategory of ${\cal D}_{K}^{s}$ on the objects of the form $(F(c), S)$ for an object $c$ of $\cal C$ and a $K$-closed sieve $S$ on $F(c)$, $C_{K}^{s}|_{{\cal D}_{F}^{s}}$ is the Grothendieck topology induced by $C_{K}^{s}$ on ${\cal D}_{F}^{s}$, $i_{F}^{s}:({\cal D}_{F}^{s}, C_{K}^{s}|_{{\cal D}_{F}^{s}})\to ({\cal D}_{K}^{s}, C_{K}^{s})$ is the morphism of sites given by the canonical inclusion functor ${\cal D}_{F}^{s}\hookrightarrow {\cal D}_{K}^{s}$, and $F_{s}$ is the morphism of sites $({\cal C}, J)\to ({\cal D}_{F}^{s}, C_{K}^{s}|_{{\cal D}_{F}^{s}})$ given by the functor $F$.

\label{corhyperclocalicintepretation}
	Let $I:{\cal C}_{\mathbb T}\to {\cal C}_{\mathbb S}$ be an interpretation of a geometric theory $\mathbb T$ into a geometric theory ${\mathbb S}$. Let ${\mathbb T}_{I}$ be the expansion of $\mathbb T$ whose signature is obtained by adding a predicate symbol $R_{\psi}$ of sorts $I(\vec{x})$ for any context $\vec{x}$ over the signature of $\mathbb T$ and any geometric formula $\psi$ in the context $I(\vec{x})$ over the signature of $\mathbb S$, and whose axioms are all the sequents whose image under the extension of $I$ sending each predicate symbol $R_{\psi}$ to the corresponding formula $\{I(\vec{x}). \psi\}$ is provable in $\mathbb S$, and let $I_{s}$ be the obvious interpretation of $\mathbb T$ into ${\mathbb T}_{I}$.
	Then the hyperconnected-localic factorization of the geometric morphism $\Set[{\mathbb S}]\to \Set[{\mathbb T}]$ induced by $I$ can be identified with the composite $\Sh(I')\circ \Sh(I_{s})$.

\label{corflatequivalence2}
		Let $({\cal C}, J)$ be a small-generated site, $\cal E$ a Grothendieck topos and $F:{\cal C}\to {\cal E}$ a $J$-continuous flat functor inducing a geometric morphism $f:{\cal E}\to \Sh({\cal C}, J)$. Then $f$ is an equivalence if and only if the following conditions are satisfied:
		\begin{enumerate}[(i)]
			\item $F$ is cover-reflecting;

			\item for every subobject $A\mono F(c)$ in $\cal E$ there exists a ($J$-closed) sieve $R$ on $c$ such that $A$ is the union of the images of the arrows $F(f)$ for $f\in R$;

			\item the objects of the form $F(c)$ for $c\in {\cal C}$ form a separating set for the topos $\cal E$.
		\end{enumerate}

\label{corsyntacticMorita}
	Let $I:{\cal C}_{\mathbb T}\to {\cal C}_{\mathbb S}$ be an interpretation of a geometric theory $\mathbb T$ into a geometric theory ${\mathbb S}$. Then $I$ induces a Morita-equivalence between $\mathbb T$ and $\mathbb S$ if and only if the following conditions are satisfied:

	\begin{enumerate}[(i)]
		\item for every sequent $\sigma$ over the signature of $\mathbb T$, if the sequent $I(\sigma)$ is provable in $\mathbb S$ then $\sigma$ is provable in $\mathbb T$;

		\item the image of $I$ is closed under subobjects (that is, for any sorts $A_{1}, \ldots, A_{n}$ of the signature of $\mathbb T$, every geometric formula $\psi$ over the signature of $\mathbb S$ in the context $I((x_{1}^{A_{1}}, \ldots, x_{n}^{A_{n}}))$ is $\mathbb T$-provably equivalent (in its context) to a formula of the form $I(\phi)$ for a geometric formula $\phi$ over the signature of $\mathbb T$ in the context $(x_{1}^{A_{1}}, \ldots, x_{n}^{A_{n}})$); 	 

		\item for every sort $B$ of the signature of $\mathbb S$, the object $\{x^{B}. \top\}$ is $J_{\mathbb S}$-covered by objects in the image of $I$.  
	\end{enumerate}

\label{corinclusionequivalence2}
	Let $f:{\cal F}\to {\cal E}$ be a geometric morphism. Then

	\begin{enumerate}[(i)]
		\item $f$ is an inclusion if and only if $f^{\ast}$ is locally surjective and its image is closed under subobjects.

		\item $f$ is an equivalence if and only if $f^{\ast}$ is faithful, locally surjective and its image is closed under subobjects.		
	\end{enumerate}

\label{lemprop}
	Let $c, c'\in {\cal C}$, $\xi:A_{F}(c)=a_{K}(\textup{Hom}_{\cal C}(F(-),c))\to A_{F}(c')=a_{K}(\textup{Hom}_{\cal C}(F(-),c'))$ an arrow in $\Sh({\cal D}, K)$ and $R_{\xi}$ the functional relation from $\textup{Hom}_{\cal C}(F(-),c)$ to $\textup{Hom}_{\cal C}(F(-),c')$ associated with it as in Remark \ref{remfunctionalrelations}(c). Then 
	\begin{enumerate}[(i)]
		\item For any arrows $f:c''\to c$ and $g:c''\to c'$, $\xi\circ A_{F}(f)=A_{F}(g)$ if and only if for every $x:F(e)\to c''$, $(f\circ x, g\circ x)\in R_{\xi}$. 

		\item There exist a family of arrows $f_{i}:c_{i}\to c$ in $\cal C$ which is sent by $A_{F}$ to an epimorphic family and a family of arrows $g_{i}:c_{i}\to c'$ in $\cal C$ such that $\xi\circ A_{F}(f_{i})=A_{F}(g_{i})$ for all $i$ if and only if there exists a family $(u_{j}, v_{j})$ of elements of $R_{\xi}$ such that the family $\{A_{F}(u_{j})\}$ is epimorphic and for any arrow $s:F(e)\to \textup{dom}(u_{j})=\textup{dom}(v_{j})$ in $\cal C$, $(u_{j}\circ s, v_{j}\circ s)\in R_{\xi}$.
	\end{enumerate}

\label{propsatisfactionconditionii}
	Let  $F:({\cal D}, K)\to ({\cal C}, J)$ be a comorphism of sites. Then the flat functor $A_{F}:{\cal C}\to \Sh({\cal D}, K)$ satisfies condition (ii) of Corollary \ref{corinclusionflatfunctor} if and only if for every $K$-functional relation $R$ from $\textup{Hom}_{\cal C}(F(-), c)$ to $\textup{Hom}_{\cal C}(F(-), c')$ in $[{\cal D}^{\textup{op}}, \Set]$ there exists a family $(f_{i}, g_{i})$ of arrows $f_{i}:\textup{dom}(f_{i}) \to c$ and $g_{i}:\textup{dom}(g_{i}) \to c'$ with common domain $\textup{dom}(f_{i})=\textup{dom}(g_{i})$ such that
	\begin{itemize}
		\item for any arrow $x:F(e)\to c$ there exists a $K$-covering sieve $T$ on $e$ such that, for every $t\in T$, $x\circ F(t)$ factors through some $f_{i}$;

		\item for any arrow $x:F(e)\to \textup{dom}(f_{i})=\textup{dom}(g_{i})$ in $\cal C$, $(f_{i}\circ x, g_{i}\circ x)\in R$.
	\end{itemize}
In particular, this condition is satisfied if $F$ is $K$-full.   

If $F$ is cover-preserving then the conjunction of the two conditions above is equivalent to the requirement that for any $(f,g)\in R$ and any arrow $x:F(e)\to \textup{dom}(f)=\textup{dom}(g)$ in $\cal C$, $(f\circ x, g\circ x)\in R$.

\label{lemmacomorphisminclusion}
Let $F:({\cal D}, K)\to ({\cal C}, J)$ be a comorphism of sites. Then for any object $d$ of $\cal D$ and any arrow $g:d'\to d$ in $\cal D$, the arrows $\xi:A_{F}(F(d'))\to l'(d)$ such that $\xi\circ \chi_{d'}=l'(g)$ can be identified with the relations $R$ from $\textup{Hom}_{\cal C}(F(-),F(d'))$ to $\textup{Hom}_{\cal D}(-,d)$ which assign to each object $e$ of $\cal C$ a collection $R(e)$ of pairs of arrows $(x:F(e)\to F(d'), y:e\to d)$ in such a way that the following properties are satisfied:
		\begin{enumerate}[(i)]
		\item for any $\xi:e'\to e$ in $\cal D$, if $(x, y)\in R$ then $(x\circ F(\xi), y\circ \xi)\in R$;	

		\item  for any $e\in {\cal D}$ and any $(x, y)\in \textup{Hom}_{\cal C}(F(e), F(d'))\times \textup{Hom}_{\cal C}(e,d)$, if $\{\xi:e'\to e \mid\ (x\circ F(\xi), y\circ \xi)\in R(e')\}\in K(e)$ then $(x,y)\in R(e)$;

		\item for any $e\in {\cal D}$, if $(x, y), (x', y')\in R$ and $x=x'$ then $y\equiv_{K} y'$;  

		\item for any $e\in {\cal D}$ and any arrow $x:F(e)\to F(d')$ in $\cal C$, $\{t:e'\to e \mid \exists y:e'\to d, \,(x\circ F(t), y)\in R(e') \}\in K(e)$;

		\item for any arrow $f:e\to d'$ in $\cal D$, $(F(f), g\circ f)\in R(e)$.	
\end{enumerate}
In particular, if $F$ is $K$-full and $K$-faithful then for every $d\in {\cal D}$ the arrow $\chi_{d'}:l'(d)\to A_{F}(F(d))$ is an isomorphism.

\label{lemmacomorphismlocalic}
	Let $F:({\cal D}, K)\to ({\cal C}, J)$ be a comorphism of sites. Then for any object $d$ of $\cal D$ and any arrow $g:d'\to d$ in $\cal D$, the arrows $\xi$ to $l'(d)$ whose domain is a subobject $s:S\mono A_{F}(F(d'))$ through which $\chi_{d'}$ factors as $\chi_{d'}=s\circ \overline{\chi_{d'}}$, and such that $\xi\circ \overline{\chi_{d'}}=l'(g)$, can be identified with the relations $R$ from $\textup{Hom}_{\cal C}(F(-),F(d'))$ to $\textup{Hom}_{\cal D}(-,d)$ satisfying all the conditions of Lemma \ref{lemmacomorphisminclusion} but condition (iv). 	

The functor $F$ is $K$-faithful if and only if for every object $d$ of $\cal D$, the arrow $\chi_{d}:l'(d)\to A_{F}(F(d))$ is a monomorphism.

\label{proplocaliccomoprhismofsites}
	The geometric morphism $C_{F}:\Sh({\cal D}, K)\to \Sh({\cal C}, J)$ induced by a comorphism of sites $F:({\cal D}, K)\to ({\cal C}, J)$ is localic if and only if for every object $d$ of $\cal D$ there exist a $K$-covering sieve $\{g_{i}:d_{i}\to d \mid i\in I\}$ on $d$ and relations $R_{i}$ from $\textup{Hom}_{\cal C}(F(-),F(d_{i}))$ to $\textup{Hom}_{\cal D}(-,d)$  satisfying the conditions of Lemma \ref{lemmacomorphismlocalic}.

	In particular, if $F$ is $K$-faithful then the geometric morphism $C_{F}$ is localic.

\label{prophyperconnectedcomoprhismofsites}
	The geometric morphism $C_{F}:\Sh({\cal D}, K)\to \Sh({\cal C}, J)$ induced by a comorphism of sites $F:({\cal D}, K)\to ({\cal C}, J)$ is hyperconnected if and only if $F$ satisfies the property of Proposition \ref{propsurjectioncomorphismofsites} and for every object $c$ of $\cal C$ and any set $A$ of arrows of the form $x:F(d)\to c$ (for an object $d$ of $\cal D$) which is functorial (in the sense that if $x\in A$ then $x\circ F(g)\in A$ for any arrow $g:d'\to d$ in $\cal D$) and $K$-closed (in the sense that for any $K$-covering sieve $T$ on $d$, if $x\circ F(t)\in A$ for every $t\in T$ then $x\in A$) there exists a ($J$-closed) sieve $S$ on $c$ such that 	
	\begin{equation*}\begin{split}
	A &= \{x:F(d)\to c \mid d\in {\cal D}\textup{, } \{t:\textup{dom}(t)\to d \mid x\circ F(t)\in S\}\in K(d)\}. 
	\end{split}\end{equation*}
	If particular, if $F$ is $K$-full this latter condition is satisfied.

The geometric morphism $C_{F}:\Sh({\cal D}, K)\to \Sh({\cal C}, J)$ induced by a comorphism of sites $F:({\cal D}, K)\to ({\cal C}, J)$ is an equivalence if and only if the following conditions are satisfied:
\begin{enumerate}[(i)]
	\item for every object $d$ of $\cal D$ there exist a $K$-covering sieve $\{g_{i}:d_{i}\to d \mid i\in I\}$ on $d$ and  relations $R_{i}$ from $\textup{Hom}_{\cal C}(F(-),F(d_{i}))$ to $\textup{Hom}_{\cal D}(-,d)$ satisfying all the conditions of Lemma \ref{lemmacomorphisminclusion} but condition (iv); 

	\item $J=K^{F}$, that is, if a sieve $S$ on an object $c\in {\cal C}$ satisfies the property that for every object $d$ of $\cal D$ and arrow $x:F(d)\to c$ there exists a $K$-covering sieve $T$ on $d$ such that for every $g\in T$, $x\circ F(g)\in S$ then $S$ is $J$-covering;  

	\item for every object $c$ of $\cal C$ and any set $A$ of arrows of the form $x:F(d)\to c$ for an object $d$ of $\cal D$ which is functorial (in the sense that if $x\in A$ then $x\circ F(g)\in A$ for any arrow $g:d'\to d$ in $\cal D$) and $K$-closed (in the sense that for any $K$-covering sieve $T$ on $d$, if $x\circ F(t)\in A$ for every $t\in T$ then $x\in A$) there exists a ($J$-closed) sieve $S$ on $c$ such that 	
	\begin{equation*}\begin{split}
	A &= \{x:F(d)\to c \mid d\in {\cal D}\textup{, } \{t:\textup{dom}(t)\to d \mid x\circ F(t)\in S\}\in K(d)\}. 
	\end{split}\end{equation*}
\end{enumerate}	
	In particular, if $F$ is $K$-full and $K$-faithful and $J$-dense then $C_{F}$ is an equivalence.

\label{propmorphismcomorphismequivalence}
	Let $F:{\cal D}\to {\cal C}$ be a functor which is both a comorphism of sites and a morphism of sites $({\cal D}, K)\to ({\cal C}, J)$, where $J$ and $K$ are Grothendieck topologies respectively on $\cal C$ and $\cal D$. Then the following conditions are equivalent:

	\begin{enumerate}[(i)]
		\item The geometric morphism $C_{F}$ is an equivalence with quasi-inverse $\Sh(F)$.

		\item $F$ is $K$-full and $J$-dense (equivalently, a dense morphism of sites $({\cal D}, K)\to ({\cal C}, J)$).
	\end{enumerate}

Subsheaves and closed subobjects
The following result is probably well-known, but we did not find a proof of it in the literature, so we give it here.

\begin{proposition}\label{propclosedsubobjects}
	Let $({\cal C}, J)$ be a small-generated site. Then for any object $F$ of $[{\cal C}^{\textup{op}}, \Set]$, denoting by $\textup{ClSub}_{[{\cal C}^{\textup{op}}, \Set]}(F)$ the sub-lattice of $\Sub_{[{\cal C}^{\textup{op}}, \Set]}(F)$ consisting of the $c_J$-closed subobjects, we have a lattice isomorphism
	\[
	\Sub_{\Sh({\cal C}, J)}(a_{J}(F))\simeq \textup{ClSub}_{[{\cal C}^{\textup{op}}, \Set]}(F)
	\]
	which sends a subobject in $\textup{ClSub}_{[{\cal C}^{\textup{op}}, \Set]}(F)$ to its image under $a_{J}$ and a subobject of $a_{J}(F)$ to the pullback of it under the unit arrow $F\to a_{J}(F)$.  
\end{proposition}

\begin{proofs}
	Given a subobject $m:A\to a_{J}(F)$ in $\Sh({\cal C}, J)$, let us associate with it the subobject $n:A'\mono F$ of $F$ defined by the following pullback diagram in $[{\cal C}^{\textup{op}}, \Set]$:
	$$
	\xymatrix{
		A' \ar[d]^{n} \ar[r] & \ar[d]^{m} A  \\
		F \ar[r]^{\eta_{F}\:\:}  & a_{J}(F)
	}
	$$
	Recall that the $c_{J}$-closure $c_{J}(k):A''\mono F$ of a subobject $k:A'\mono F$ in $[{\cal C}^{\textup{op}}, \Set]$ is characterized by the following pullback diagram:
	$$
	\xymatrix{
		A'' \ar[d]^{c_J(k)} \ar[r] & \ar[d]^{a_{J}(k)} a_J(A')  \\
		F \ar[r]^{\eta_{F}\:\:}  & a_{J}(F)
	}
	$$ 
	It thus follows that $n$ is $c_J$-closed, since by applying the pullback-preserving functor $a_J$ to the former pullback square we obtain that $m\cong a_J(n)$.
	Conversely, we associate with any $c_J$-closed subobject $n$ the subobject $a_J(n)$ of $\Sh({\cal C}, J)$. It is immediate to see that these two operations are inverse to each other, and that they are order-preserving; so they are lattice isomorphisms.
\end{proofs}

\begin{remarks}\label{remimageclosedsubobject}
	\begin{enumerate}[(a)]
		\item Given an arrow $\alpha:P\to Q$ in $[{\cal C}^{\textup{op}}, \Set]$, the $c_J$-closed subobject $Q_{\alpha}$ of $Q$ corresponding via Proposition \ref{propclosedsubobjects} to the image of the arrow $a_{J}(\alpha)$ is given by $$Q_{\alpha}(c)=\{x\in Q(c) \mid \{f:d\to c \mid Q(f)(x)\in \textup{Im}(\alpha(d))\}\in J(c) \}$$
		for any $c\in {\cal C}$.

		\item Proposition \ref{propclosedsubobjects} clearly generalizes to the setting of elementary toposes, replacing $[{\cal C}^{\textup{op}}, \Set]$ by an arbitrary elementary topos $\cal E$, $J$ by a local operator on it and $c_{J}$ by the associate closure operation on subobjects in $\cal E$.
	\end{enumerate}

\end{remarks}

Geometric morphisms and flat functors
Recall that any functor $A:{\cal C}\to {\cal E}$ from an essentially small category $\cal C$ to a Grothendieck topos $\cal E$ induces an adjuction $(L_{A} \dashv R_{A})$, where $R_{A}:{\cal E}\to [{\cal C}^{\textup{op}}, \Set]$ is the ` hom' functor $\textup{Hom}_{\cal E}(A(-),-)$ and $L_{A}:[{\cal C}^{\textup{op}}, \Set] \to {\cal E}$ is the unique (up to isomorphism) colimit-preserving functor which extends $A$ along the Yoneda embedding $y_{\cal C}:{\cal C}\to [{\cal C}^{\textup{op}}, \Set]$, in other words, the left Kan extension of $A$ along the Yoneda embedding $y_{\cal C}:{\cal C}\to [{\cal C}^{\textup{op}}, \Set]$, which sends each presheaf $P$ on $\cal C$ to the colimit of the diagram $A\circ \pi_{P}$, where $\pi_{P}:{\int P} \to {\cal C}$ is the canonical projection from the category ${\int P}$ of elements  of $P$ (see, for instance, section I.5 of \cite{MM}). The functor $A$ is said to be \emph{flat} if $L_{A}$ preserves finite limits. In this case, the pair $(L_{A}\dashv R_{A})$ defines a geometric morphism ${\cal E}\to [{\cal C}^{\textup{op}}, \Set]$. If $J$ is a Grothendieck topology on $\cal C$ and $A$ is flat then the geometric morphism $(L_{A}\dashv R_{A}):{\cal E}\to [{\cal C}^{\textup{op}}, \Set]$ factors through the canonical geometric inclusion $\Sh({\cal C}, J)\hookrightarrow [{\cal C}^{\textup{op}}, \Set]$ if and only if $A$ is $J$-continuous. In other words, we have a categorical equivalence, usually called \emph{Diaconescu's equivalence}
\[
\textbf{Geom}({\cal E}, \Sh({\cal C}, J))\simeq \textbf{Flat}_{J}({\cal C}, {\cal E}),
\]
where $\textbf{Geom}({\cal E}, \Sh({\cal C}, J))$ is the category of geometric morphisms from ${\cal E}$ to $\Sh({\cal C}, J)$ and $\textbf{Flat}_{J}({\cal C}, {\cal E})$ is the category of $J$-continuous flat functors ${\cal C}\to {\cal E}$.

In section VII.9 of \cite{MM}, the flat functors ${\cal C}\to {\cal E}$ are characterized precisely as the functors ${\cal C}\to {\cal E}$ that are \emph{filtering}, in the sense of the following result:

\begin{theorem}[Theorem VII.9.1 \cite{MM}]\label{filteringfunctor}
	A functor $A:{\cal C}\to {\cal E}$ is flat if and only if it is filtering in the sense that it satisfies the following conditions:	
	\begin{enumerate}[(i)]
		\item The family of arrrows $A(c)\to 1_{\cal E}$ (for $c\in {\cal C}$) is epimorphic in $\cal E$;

		\item For any objects $c$ and $d$ of $\cal C$, the family of arrows of the form $\langle A(u), A(v)\rangle :A(b)\to A(c)\times A(d)$, where $b$ is an object of $\cal C$ $u$ and $v$ are arrows respectively $b\to c$ and $b\to d$ in $\cal C$, is epimorphic in $\cal E$;

		\item For any two arrows $u, v:c\to d$ in $\cal C$, let $i:\textup{Eq}(A(u), A(v))\mono A(c)$ be the equalizer of $A(u)$ and $A(v)$ in $\cal E$. Then the family of factorizations $A(b)\to \textup{Eq}(A(u), A(v))$ through $i$ of arrows of the form $A(w):A(b)\to A(c)$, where $w:b\to c$ is an arrow in $\cal C$ such that $u\circ w=v\circ w$, is epimorphic. 		
	\end{enumerate}
\end{theorem}

Inclusions
To characterize the comorphisms of sites which give rise to a geometric inclusion, we shall use the criterion provided by Corollary \ref{corinclusionflatfunctor}. 

The following lemma expresses certain properties of arrows in the image of the functor $A_{F}$ introduced above in terms of functional relations associated with them.

\begin{lemma}\label{lemprop}
	Let $c, c'\in {\cal C}$, $\xi:A_{F}(c)=a_{K}(\textup{Hom}_{\cal C}(F(-),c))\to A_{F}(c')=a_{K}(\textup{Hom}_{\cal C}(F(-),c'))$ an arrow in $\Sh({\cal D}, K)$ and $R_{\xi}$ the functional relation from $\textup{Hom}_{\cal C}(F(-),c)$ to $\textup{Hom}_{\cal C}(F(-),c')$ associated with it as in Remark \ref{remfunctionalrelations}(c). Then 
	\begin{enumerate}[(i)]
		\item For any arrows $f:c''\to c$ and $g:c''\to c'$, $\xi\circ A_{F}(f)=A_{F}(g)$ if and only if for every $x:F(e)\to c''$, $(f\circ x, g\circ x)\in R_{\xi}$. 

		\item There exist a family of arrows $f_{i}:c_{i}\to c$ in $\cal C$ which is sent by $A_{F}$ to an epimorphic family and a family of arrows $g_{i}:c_{i}\to c'$ in $\cal C$ such that $\xi\circ A_{F}(f_{i})=A_{F}(g_{i})$ for all $i$ if and only if there exists a family $(u_{j}, v_{j})$ of elements of $R_{\xi}$ such that the family $\{A_{F}(u_{j})\}$ is epimorphic and for any arrow $s:F(e)\to \textup{dom}(u_{j})=\textup{dom}(v_{j})$ in $\cal C$, $(u_{j}\circ s, v_{j}\circ s)\in R_{\xi}$.
	\end{enumerate}
\end{lemma}

\begin{proofs}
	(i) By Remark \ref{remfunctionalrelations}(c), $(f\circ x, g\circ x)\in R_{\xi}$ if and only if $\xi \circ \eta^{c} (f\circ x)=\eta^{c'}(g\circ x)$, where $\eta^{c}:\textup{Hom}_{\cal C}(F(-),c) \to a_{K}(\textup{Hom}_{\cal C}(F(-),c))$ and $\eta^{c'}:\textup{Hom}_{\cal C}(F(-),c') \to a_{K}(\textup{Hom}_{\cal C}(F(-),c'))$ are the canonical unit arrows. But $\xi \circ \eta^{c} (f\circ x)=(\xi\circ A_{F}(f)\circ \eta^{c''})(x)$ and $\eta^{c'}(g\circ x)=(A_{F}(g)\circ \eta^{c''})(x)$, where $\eta^{c''}:\textup{Hom}_{\cal C}(F(-),c'') \to a_{K}(\textup{Hom}_{\cal C}(F(-),c''))$ is the canonical unit arrow.

	(ii) Let us suppose that there exist a family of arrows $f_{i}:c_{i}\to c$ in $\cal C$ which is sent by $A_{F}$ to an epimorphic family and a family of arrows $g_{i}:c_{i}\to c'$ in $\cal C$ such that $\xi\circ A_{F}(f_{i})=A_{F}(g_{i})$ for all $i$. Then we may take as arrows $(u_{j}, v_{j})$ those of the form $(f_{i}\circ x, g_{i}\circ x)$ for $x$ an arrow $F(e)\to c_{i}$ for some $i\in I$. By (i), every pair of the form $(f_{i}\circ x, g_{i}\circ x)$ is in $R_{\xi}$, so it remains to show that the family of arrows $\{A_{F}(u_{j})\}$ is epimorphic (equivalently, for any arrow $u:F(e)\to c$ there exists a $K$-covering sieve $T$ on $e$ such that $u\circ F(t)$ factors through some $u_{j}$ for every $t\in T$). But this is clear since, the family $\{A_{F}(f_{i}) \mid i\in I \}$ being epimorphic, there is a $K$-covering sieve $T_{u}$ on $e$ such that, for every $t\in T_{u}$, $u\circ F(t)$ factors through some $f_{i}$, that is, is of the form $f_{i}\circ x$ for some arrow $x$. 

	Conversely, if there exists a family $(u_{j}, v_{j})$ of elements of $R_{\xi}$ such that the family $\{A_{F}(u_{j})\}$ is epimorphic and for any arrow $s:F(e)\to \textup{dom}(u_{j})=\textup{dom}(v_{j})$ in $\cal C$, $(u_{j}\circ s, v_{j}\circ s)\in R_{\xi}$ then by (i) $\xi\circ A_{F}(u_{j})=A_{F}(v_{j})$ for each $j$. So we may take as family of arrows $(f_{i}, g_{i})$ precisely the family of arrows $(u_{j}, v_{j})$.      
\end{proofs}

\begin{proposition}\label{propsatisfactionconditionii}
	Let  $F:({\cal D}, K)\to ({\cal C}, J)$ be a comorphism of sites. Then the flat functor $A_{F}:{\cal C}\to \Sh({\cal D}, K)$ satisfies condition (ii) of Corollary \ref{corinclusionflatfunctor} if and only if for every $K$-functional relation $R$ from $\textup{Hom}_{\cal C}(F(-), c)$ to $\textup{Hom}_{\cal C}(F(-), c')$ in $[{\cal D}^{\textup{op}}, \Set]$ there exists a family $(f_{i}, g_{i})$ of arrows $f_{i}:\textup{dom}(f_{i}) \to c$ and $g_{i}:\textup{dom}(g_{i}) \to c'$ with common domain $\textup{dom}(f_{i})=\textup{dom}(g_{i})$ such that
	\begin{itemize}
		\item for any arrow $x:F(e)\to c$ there exists a $K$-covering sieve $T$ on $e$ such that, for every $t\in T$, $x\circ F(t)$ factors through some $f_{i}$;

		\item for any arrow $x:F(e)\to \textup{dom}(f_{i})=\textup{dom}(g_{i})$ in $\cal C$, $(f_{i}\circ x, g_{i}\circ x)\in R$.
	\end{itemize}
In particular, this condition is satisfied if $F$ is $K$-full.   

If $F$ is cover-preserving then the conjunction of the two conditions above is equivalent to the requirement that for any $(f,g)\in R$ and any arrow $x:F(e)\to \textup{dom}(f)=\textup{dom}(g)$ in $\cal C$, $(f\circ x, g\circ x)\in R$.
\end{proposition}

\begin{proofs}
	Recall that condition (ii) of Corollary \ref{corinclusionflatfunctor} states that for every $c, c'\in {\cal C}$ and any arrow $\xi:A_{F}(c)\to A_{F}(c')$ in $\Sh({\cal D}, K)$, there exist a family of arrows $f_{i}:c_{i}\to c$ in $\cal C$ which is sent by $A_{F}$ to an epimorphic family and a family of arrows $g_{i}:c_{i}\to c'$ in $\cal C$ such that $\xi\circ A_{F}(f_{i})=A_{F}(g_{i})$ for all $i$.

	By Theorem \ref{thmfunctionalrelations}, the arrows $$\xi:A_{F}(c)=a_{K}(\textup{Hom}_{\cal C}(F(-),c))\to a_{K}(\textup{Hom}_{\cal C}(F(-),c'))=A_{F}(c')$$ in $\Sh({\cal D}, K)$ correspond to the $K$-functional relations $R_{\xi}$ from $\textup{Hom}_{\cal C}(F(-),c)$ to $\textup{Hom}_{\cal C}(F(-),c')$ in $[{\cal D}^{\textup{op}},\Set]$. 

	The first part of the proposition thus follows immediately from Lemma \ref{lemprop} by observing that a family of arrows $\{A_{F}(u_{j})\}$ is epimorphic if and only if for any arrow $x:F(e)\to c$ there exists a $K$-covering sieve $T$ on $e$ such that, for every $t\in T$, $x\circ F(t)$ factors through some $u_{j}$. 

	If $F$ is $K$-full then, for any arrow $\xi:A_{F}(c) \to A_{F}(c')$, the family of pairs of arrows in $R_{\xi}$ satisfies both conditions in the statement of the Proposition. The first condition is satisfied since, $R_{\xi}$ being a $K$-functional relation, the family of arrows $\{A_{F}(x) \mid x\in \pi_{1}(R_{\xi}) \}$, where $\pi_{1}$ is the canonical projection $\textup{Hom}_{\cal C}(F(-),c)\times \textup{Hom}_{\cal C}(F(-),c') \to \textup{Hom}_{\cal C}(F(-),c)$, is epimorphic in $\Sh({\cal D}, K)$, while the second holds by the following argument. Given $(f,g)\in R_{\xi}$ and $x:F(e)\to  \textup{dom}(f)=\textup{dom}(g)$, the $K$-fullness of $F$ implies that there exist a $K$-covering family $T$ on $e$ and for each $t\in T$ an arrow $s_{t}:\textup{dom}(t)\to e$ such that $x\circ F(t)=F(s_{t})$. Now, by the $K$-closure property of $R_{\xi}$, the condition $(f\circ x, g\circ x)\in R_{\xi}$ is equivalent to $(f\circ x\circ F(t),  g\circ x\circ F(t))\in R_{\xi}$ for every $t\in T$. But $(f\circ x\circ F(t),  g\circ x\circ F(t))=(f\circ F(s_{t}), g\circ F(s_{t}))$, and  $(f\circ F(s_{t}), g\circ F(s_{t}))\in R_{\xi}$ by the functoriality of $R_{\xi}$. 

	It remains to prove the last part of the proposition, namely that, provided that $F$ is cover-preserving, if $R$ satisfies the two conditions above then $R$ is closed under composition on the right with arbitrary arrows in $\cal C$. Note that the converse direction follows from the fact that if $R$ satisfies this property then, by taking the family $\{(f_i, g_i)\}$ to consist of the pairs in $R$, the first condition in the proposition is automatically satisfied by the $K$-functionality of $R$. So, let us suppose that $(f:F(e)\to c, g:F(e)\to c')\in R$ and that $x:F(a)\to F(e)$ is an arrow in $\cal C$; we want to show that $(f\circ x, g\circ x)\in R$. By the first condition, there is a $K$-covering sieve $T$ on $e$ such that, for each $t\in T$, $f\circ F(t)$ factors through some $f_{i_{t}}$, say, $f\circ F(t)=f_{i_{t}}\circ u_{i}^{t}$. Now, by the functoriality of $R$, $(f, g)\in R$ implies that $(f\circ F(t), g\circ F(t))\in R$. On the other hand, the second condition in the proposition implies that $(f_{i_{t}}\circ u_{i}^{t}, g_{i_{t}}\circ u_{i}^{t})\in R$. So, the $K$-functionality of $R$ implies that $g\circ F(t) \equiv_{K} g_{i_{t}}\circ u_{i}^{t}$. Since $F$ is cover-preserving, the sieve $\langle F(T)\rangle $ generated by the arrows $F(t)$ for $t\in T$ is $J$-covering; therefore its pullback along $x$ is also $J$-covering and hence by the covering-lifting property there is a $K$-covering sieve $H$ on $a$ such that for each $h\in H$, $x\circ F(h)=F(t_{h})\circ z_{h}$ for some arrow $t_{h}\in T$ and some arrow $z_{h}:F(\textup{dom}(h))\to F(\textup{dom}(t_{h}))$. Now, by the $K$-closure of $R$, $(f\circ x, g\circ x)\in R$ if and only if for every $h\in H$, $(f\circ x\circ F(h), g\circ x\circ F(h))\in R$. But $(f\circ x\circ F(h), g\circ x\circ F(h))=(f_{i_{t_{h}}}\circ u_{i}^{t_{h}}\circ z_{h}, g\circ F(t_{h})\circ  z_{h})$. Now, we have $g\circ F(t_{h}) \equiv_{K} g_{i_{t_{h}}}\circ u_{i}^{t_{h}}$, whence $g\circ F(t_{h}) \circ z_{h} \equiv_{K} g_{i_{t_{h}}}\circ u_{i}^{t_{h}}\circ z_{h}$. Since $R$ is a $K$-functional relation, the condition $(f_{i_{t_{h}}}\circ u_{i}^{t_{h}}\circ z_{h}, g\circ F(t_{h})\circ  z_{h})\in R$ is equivalent to $(f_{i_{t_{h}}}\circ u_{i}^{t_{h}}\circ z_{h}, g_{i_{t_{h}}}\circ u_{i}^{t_{h}}\circ z_{h})\in R$ (cf. Proposition \ref{propfuncionalassignment}), and this is satisfied by the second condition in the proposition.     
\end{proofs}


For investigating the satisfaction of condition (i) of Corollary \ref{corinclusionflatfunctor}, we need the following lemma. Notice that if $F:({\cal D}, K)\to ({\cal C}, J)$ is a comorphism of sites then for any $d\in {\cal D}$ we have an arrow $\chi_{d}:l'(d)\to A_{F}(F(d))$ corresponding, via the associated sheaf adjuntion and the Yoneda embedding, to the element of $A_{F}(F(d))(d)$ given by the identity arrow on $F(d)$.

\begin{lemma}\label{lemmacomorphisminclusion}
Let $F:({\cal D}, K)\to ({\cal C}, J)$ be a comorphism of sites. Then for any object $d$ of $\cal D$ and any arrow $g:d'\to d$ in $\cal D$, the arrows $\xi:A_{F}(F(d'))\to l'(d)$ such that $\xi\circ \chi_{d'}=l'(g)$ can be identified with the relations $R$ from $\textup{Hom}_{\cal C}(F(-),F(d'))$ to $\textup{Hom}_{\cal D}(-,d)$ which assign to each object $e$ of $\cal C$ a collection $R(e)$ of pairs of arrows $(x:F(e)\to F(d'), y:e\to d)$ in such a way that the following properties are satisfied:
		\begin{enumerate}[(i)]
		\item for any $\xi:e'\to e$ in $\cal D$, if $(x, y)\in R$ then $(x\circ F(\xi), y\circ \xi)\in R$;	

		\item  for any $e\in {\cal D}$ and any $(x, y)\in \textup{Hom}_{\cal C}(F(e), F(d'))\times \textup{Hom}_{\cal C}(e,d)$, if $\{\xi:e'\to e \mid\ (x\circ F(\xi), y\circ \xi)\in R(e')\}\in K(e)$ then $(x,y)\in R(e)$;

		\item for any $e\in {\cal D}$, if $(x, y), (x', y')\in R$ and $x=x'$ then $y\equiv_{K} y'$;  

		\item for any $e\in {\cal D}$ and any arrow $x:F(e)\to F(d')$ in $\cal C$, $\{t:e'\to e \mid \exists y:e'\to d, \,(x\circ F(t), y)\in R(e') \}\in K(e)$;

		\item for any arrow $f:e\to d'$ in $\cal D$, $(F(f), g\circ f)\in R(e)$.	
\end{enumerate}
In particular, if $F$ is $K$-full and $K$-faithful then for every $d\in {\cal D}$ the arrow $\chi_{d'}:l'(d)\to A_{F}(F(d))$ is an isomorphism.
\end{lemma}

\begin{proofs}
The first part of the lemma follows from the proof of Theorem \ref{thmfunctionalrelations}. It thus remains to show that if $F$ is $K$-full and $K$-faithful then there exists a relation which verifies the conditions in the statement of the lemma and is inverse to $\chi_{d'}$. We can define a relation $R_{F}$ on pairs of arrows $(x:F(e)\to F(d), y:e\to d)$ by stipulating that $(x,y)\in R_{F}$ if and only if $F(y)=x$. If $F$ is $K$-faithful and $K$-full then the relation $R_{F}$ clearly satisfies all the conditions of the lemma for the family of objects $\{c_{i} \mid i\in I\}$ given by the singleton $\{F(d)\}$ except for the closure condition (ii), which, by Remark \ref{remfunctionalrelations}(b), can be made to hold (without affecting the satisfaction of the other conditions) by taking its $K$-closure. The corresponding arrow $A_{F}(F(d))\to l'(d)$ (via the bijection of Theorem \ref{thmfunctionalrelations}) is actually inverse to the arrow $\chi_{d}$ (cf. Proposition \ref{proplocalfullnessandfaithfulness}), as required. 	
\end{proofs}

\begin{proposition}\label{propinclusioncomoprhismofsites}
	The geometric morphism $C_{F}:\Sh({\cal D}, K)\to \Sh({\cal C}, J)$ induced by a comorphism of sites $F:({\cal D}, K)\to ({\cal C}, J)$ is an inclusion if and only if $F$ satisfies the condition of Proposition \ref{propsatisfactionconditionii} and for every object $d$ of $\cal D$ there exist a $K$-covering family $\{g_{i}:d_{i}\to d \mid i\in I\}$ and arrows $\xi_{i}:A_{F}(F(d_{i}))\to l'(d)$ in $\Sh({\cal D}, K)$ such that $\xi_{i}\circ \chi_{d_{i}}=l'(g_{i})$ (equivalently, relations $R_{i}$ from $\textup{Hom}_{\cal C}(F(-),F(d_{i}))$ to $\textup{Hom}_{\cal D}(-,d)$  satisfying the conditions of Lemma \ref{lemmacomorphisminclusion}). 

	In particular, if $F$ is $K$-full and $K$-faithful then the geometric morphism $C_{F}$ is an inclusion. Conversely, if $F$ is cover-preserving and $C_{F}$ is an inclusion then $F$ is $K$-full.

	If $F$ is $(K, J)$-continuous (in the sense of Definition \ref{defcanonicalfunctor}) then $C_{F}$ is an inclusion if and only if $F$ is $K$-full and $K$-faithful.
\end{proposition} 

\begin{proofs}
By Corollary \ref{corinclusionflatfunctor}, $C_{F}$ is an inclusion if and only if conditions (i) and (ii) of the Corollary are satified by the flat functor $A_{F}$. Condition (ii) is equivalent to the condition of Proposition \ref{propsatisfactionconditionii}. On the other hand, condition (i) is satisfied by $A_{F}$ if and only if for each $d\in {\cal D}$, there exists a set $\{c_{j}\}$ of objects of $\cal C$ and an epimorphic family of arrows $\xi'_{j}:A_{F}(c_{j})\to l'(d)$. But, by using Proposition \ref{propfunctionalrelationmonoepi}(ii), one can easily see that this amounts to the existence of a $K$-covering family $\{g_{i}:d_{i}\to d \mid i\in I\}$ on $d$ and for each $i\in I$ an arrow $u_{i}:F(d_{i})\to c_{j_{i}}$ in $\cal C$ (for some $j_{i}$) such that $l'(g_{i})=\xi'_{j_{i}}\circ A_{F}(u_{i})\circ \chi_{d_{i}}$. So the composite of the arrow $\xi_{i}:=\xi'_{j_{i}}\circ A_{F}(u_{i}):A_{F}(F(d_{i}))\to l'(d)$ with $\chi_{d_{i}}$ is equal to $l'(g_{i})$.  

If $F$ is $K$-full and $K$-faithful then by Proposition \ref{propsatisfactionconditionii} $F$ satisfies the condition in it and by Lemma \ref{lemmacomorphisminclusion} for every $d\in {\cal D}$ the arrow $\chi_{d'}:l'(d)\to A_{F}(F(d))$ is an isomorphism whence we can take the trivial covering family on each $d$ to make the condition of the proposition satisfied. 

Let us now show that if $C_{F}$ is an inclusion and $F$ is cover-preserving then $F$ is $K$-full.
Let $f, f':e\to d$ be arrows in $\cal D$ such that $F(f)=F(f')$. Let $\{g_{i}:d_{i}\to d \mid i\in I\}$ be a $K$-covering family and $\xi_{i}:A_{F}(F(d_{i}))\to l'(d)$ be arrows in $\Sh({\cal D}, K)$, corresponding to $K$-functional relations $R_{i}$ from $\textup{Hom}_{\cal C}(F(-),F(d_{i}))$ to $\textup{Hom}_{\cal D}(-,d)$, such that $\xi_{i}\circ \chi_{d_{i}}=l'(g_{i})$. Let us first prove that, for any $i\in I$, we have $\chi_{d}\circ \xi_{i}=A_{F}(F(g_{i}))$. The $K$-functional relation corresponding to this arrow is the composite $R_{i}'$ of $R_{i}$ with the relation $R_{\chi_{d}}$ associated with $\chi_{d}$. Since $(1_{F(d_{i})}, g_{i})\in R_{i}$ (this follows from the fact that $R_{i}$ satisfies property (v) of Lemma \ref{lemmacomorphisminclusion} with respect to the arrow $g_{i}$) and $(g_{i}, F(g_{i})\in R_{\chi_{d}}$, we have $(1_{F(d_{i})}, F(g_{i}))\in R_{i}'$. So, by the last part of Proposition \ref{propsatisfactionconditionii}, for any arrow $x:F(e)\to F(d_{i})$, $(x, F(g_{i})\circ x)\in R_{i}'$; in other words, $\chi_{d}\circ \xi_{i}=A_{F}(F(g_{i}))$, as required. 

The sieve $\langle \{F(g_i) \mid i\in I\}\rangle $ generated by the arrows $F(g_i)$ for $i\in I$ is $J$-covering; so, for any arrow $y:F(e)\to F(d)$ in $\cal C$, its pullback along $y$ is also $J$-covering, whence by the covering-lifting property there is a $K$-covering sieve $H$ on $e$ such that for each $h\in H$, $y\circ F(h)=F(g_{i_{h}})\circ z_{h}$ for some $i_{h}\in I$ and some arrow $z_{h}:F(\textup{dom}(h))\to F(d_{i_{h}})$. Now, since $R_{i}$ is $K$-functional, there is a $K$-covering sieve $T_{h}$ on $\textup{dom}(h)$ and for each $t\in T_{h}$ an arrow $a_{t}:\textup{dom}(t)\to d$ such that $(z_{h}\circ F(t), a_{t})\in R_{i}$. Then, from the fact (proved above) that $\chi_{d}\circ \xi_{i}=A_{F}(F(g_{i}))$ it follows that $F(a_{t})$ is $K$-locally equal to $F(g_{i_{h}})\circ z_{h}\circ F(t)$, that is, there is a $K$-covering sieve $W_{t}$ on $\textup{dom}(t)$ such that $F(a_{t})\circ F(w)=F(g_{i_{h}})\circ z_{h}\circ F(t)\circ F(w)=y\circ F(h)\circ F(t)\circ F(w)$ for each $w\in W_{t}$. Therefore the $K$-covering sieve $U$ given by the multiomposite of $H$, the $T_{h}$'s (for $h\in H$) and the $W_{t}$'s (for $t\in T_{h}$) satisfies the property that for any $u\in U$ there is an arrow $a'_{u}:\textup{dom}(u)\to d$ such that $y\circ F(u)=F(a'_{u})$ for each $u\in U$ (indeed, if $u=h\circ t\circ w$ then we can take $a'_{u}=a_{t}\circ w$). So $F$ is $K$-full, as desired.   

It remains to prove the last part of the proposition. We have already shown that the condition on $F$ being $K$-faithful and $K$-full is a sufficient condition for $C_{F}$ to be an inclusion. We want to prove that this condition is also necessary if $F$ is $(K, J)$-continuous. But this follows from the fact that, by Corollary \ref{correstrictioncomorphism}, we have a commutative diagram

		$$
\xymatrix{
	{\mathcal C} \ar[r]^F \ar[d]_{l'} &{\cal D} \ar[d]^{l} \\
	\Sh({\cal D}, K) \ar[r]^{(C_{F})_{!}} & \Sh({\cal C}, J)
}
$$ 
in light of Proposition \ref{proplocalproperties}(i)-(ii) and Remark \ref{remcoveringliftingstrictequality}. 
\end{proofs}

\begin{remark}\label{remarkinclusion}
	If $J$ and $K$ are the trivial topologies then one may deduce from Proposition \ref{propinclusioncomoprhismofsites} the following criterion for the essential geometric morphism $C_{F}:[{\cal D}^{\textup{op}},\Set]\to [{\cal C}^{\textup{op}},\Set]$ induced by $F$ to be an inclusion: $C_{F}$ is an inclusion if and only if $F$ is full and faithful. 

	Indeed, the `if' direction follows immediately from the proposition, while the converse one can be proved as follows. The fullness of $F$ follows from the last part of the proposition, while its faithfulness follows from the fact that the condition in the proposition implies that, for every $d\in {\cal D}$, there is an arrow $\xi:A_{F}(F(d))\to l'(d)$ such that $\xi\circ \chi_{d}=1_{l'(d)}$. 

	An alternative way of proving that if $C_{F}$ is an inclusion then $F$ is full and faithful is to observe that, the inverse image functor of the geometric morphism $C_{F}$ having adjoints on both sides, the right adjoint is full and faithful if and only if the left adjoint is; but this latter condition implies that $F$ is full and faithful, since $F$ can be recovered from this functor as its restriction to the representables.
\end{remark}



The surjection-inclusion factorization of the geometric morphism induced by a comorphism of sites admits a particularly simple description when the latter is cover-preserving, as shown by the following proposition. 

\begin{proposition}\label{propsurinclfactorizationcomorphismofsites}
	Let $F:({\cal D}, K)\to ({\cal C}, J)$ be a comorphism of sites which is cover-preserving. Then the surjection-inclusion factorization of the geometric morphism $C_{F}:\Sh({\cal D}, K)\to \Sh({\cal C}, J)$ induced by $F$ can be identified with $C_{i}\circ C_{F'}$, where $F'$ is the functor $F$ regarded as a comorphism of sites from $({\cal D}, K)$ to the site $({\cal C}', J')$, where ${\cal C}'$ is the full subcategory of $\cal C$ on the objects in the image of $F$ and $J'$ is the smallest Grothendieck topology on ${\cal C}'$ making the inclusion $i$ of ${\cal C}'$ into ${\cal C}$ a comorphism of sites to $({\cal C}, J)$.	
\end{proposition}

\begin{proofs}
	Since $F$ is cover-preserving, by definition of the Grothendieck topology $J'$, $F'$ is also cover-preserving (cf. Corollary \ref{corliftcomorphismsofsites}). It is also surjective on objects, so, by Proposition \ref{propsurjectioncomorphismofsites}, $C_{F'}$ is a surjection. On the other hand, $i$ is full and faithful, so, by Proposition \ref{propinclusioncomoprhismofsites}, $C_{i}$ is an inclusion. By the uniqueness (up to equivalence) of the surjection-inclusion factorization, it follows that $C_{i}\circ C_{F'}$ is `the' surjection-inclusion factorization of $C_{F}$, as required.
\end{proofs}

\begin{remark}
	Proposition \ref{propsurinclfactorizationcomorphismofsites} generalizes the result (cf. Example A4.2.12(b) \cite{El}) describing the surjection-inclusion factorization of the essential geometric morphism induced by an arbitrary functor between small categories. 
\end{remark}

A $J$-continuous flat  functor $F:{\cal C} \to {\cal E}$ induces a geometric inclusion if and only if it satisfies the following conditions:  
	\begin{enumerate}[(i)]	
		\item every object of $\cal E$ can be covered by objects which are in the image of $F$;
		\item for every $x, y\in {\cal C}$ and any arrow $g:F(x)\to F(y)$ in $\cal E$, there exist a family of arrows $f_{i}:x_{i}\to x$ which is sent by $F$ to an epimorphic family and a family of arrows $g_{i}:x_{i}\to y$ such that $g\circ F(f_{i})=F(g_{i})$ for all $i$.
	\end{enumerate}  
\end{corollary}

